window.GLOSS = [{"t":"WAL","f":"Write-Ahead Logging · 预写日志","d":"改数据页之前，先把这次修改的日志落盘。崩溃后靠日志恢复，提交时不用强刷数据页。","a":["预写日志"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"LSN","f":"Log Sequence Number · 日志序列号","d":"日志记录的全局递增编号，用来判断一条修改有没有落到数据页上。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"pageLSN","f":"Page LSN · 页的最新 LSN","d":"这一页最后一次被修改对应的日志序号，存在页头里。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"MVCC","f":"Multi-Version Concurrency Control · 多版本并发控制","d":"写操作生成新版本、不覆盖旧版本，读操作看自己快照里的版本，读写互不阻塞。","a":["多版本并发控制"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"2PL","f":"Two-Phase Locking · 两阶段封锁","d":"事务先只加锁（增长期），一旦放锁就不能再加锁（收缩期），由此保证冲突可串行化。","a":["两阶段封锁"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"缓冲池","f":"Buffer Pool","d":"数据库自己管理的一块内存，缓存磁盘页。读写页都经过它，由替换策略决定淘汰谁。","a":["Buffer Pool"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"关系代数","f":"Relational Algebra · 关系代数","d":"一组操作关系的算子，如选择、投影、连接，规定每一步怎么做。查询计划就长这样。","a":["Relational Algebra"],"h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"schema","f":"Schema · 模式","d":"用某种数据模型描述一个具体数据库：有哪些表、哪些列、什么类型。","a":["Schema"],"h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"数据独立性","f":"Data Independence · 数据独立性","d":"应用只面对逻辑层，不依赖数据怎么存。所以数据库能换存储布局，应用不用改。","a":["物理数据独立性","逻辑数据独立性"],"h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"笛卡尔积","f":"Cartesian Product · 笛卡尔积","d":"两张表的行两两配对，结果行数是两表之积。除非明确要求，优化器绝不该产生它。","a":["Cartesian Product","交叉连接"],"h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"声明式","f":"Declarative · 声明式","d":"只说要什么结果，不说怎么算。SQL 是声明式的，数据库才有自由选择执行方式。","h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"谓词","f":"Predicate · 谓词","d":"结果为真或假的条件，比如 WHERE 里的 age > 30，决定哪些元组留下。","h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"DML","f":"Data Manipulation Language · 数据操纵语言","d":"读写数据的语言，包括 INSERT、UPDATE、DELETE，只读的 SELECT 也算。","h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"相关子查询","f":"Correlated Subquery · 相关子查询","d":"内层引用了外层的列，外层每一行都要重算一次内层。优化器不改写时就是嵌套循环。","a":["Correlated Subquery"],"h":"../ch01-foundations.html#L02","n":"详见 #02 现代 SQL"},{"t":"CTE","f":"Common Table Expression · 公用表表达式","d":"用 WITH 在查询内定义一张临时结果表，后面像真表一样引用，查询结束就扔。","a":["公用表表达式"],"h":"../ch01-foundations.html#L02","n":"详见 #02 现代 SQL"},{"t":"窗口函数","f":"Window Function · 窗口函数","d":"对每一行算一个基于相关行的值，比如组内排名、移动平均，不把多行合成一行。","h":"../ch01-foundations.html#L02","n":"详见 #02 现代 SQL"},{"t":"LATERAL","f":"LATERAL JOIN","d":"让后面的子查询引用前面子查询的结果，像两层 for 循环：外层每行跑一次内层。","a":["LATERAL JOIN","JOIN LATERAL","CROSS APPLY"],"h":"../ch01-foundations.html#L02","n":"详见 #02 现代 SQL"},{"t":"QUALIFY","f":"QUALIFY 子句","d":"直接过滤窗口函数的结果，不用再套一层子查询。DuckDB 支持。","h":"../homework.html#HW1","n":"详见 HW1 HW1：SQL 查询"},{"t":"UPSERT","f":"Update + Insert · 有则更新、无则插入","d":"插入时撞上已有的键就改成更新，否则正常插入。常写成 INSERT … ON CONFLICT。","a":["ON CONFLICT"],"h":"../homework.html#HW1","n":"详见 HW1 HW1：SQL 查询"},{"t":"磁盘导向架构","f":"Disk-Oriented DBMS · 磁盘导向架构","d":"主数据放在磁盘上，用到时先读进内存才能处理。全课的设计都围绕这个假设展开。","a":["Disk-Oriented DBMS"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"块可寻址","f":"Block-Addressable · 块可寻址","d":"最小访问单位是块，要一个字节也得读整块。内存才是字节可寻址，所以数据库按页组织。","a":["字节可寻址","block-addressable","byte-addressable"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"顺序 I/O","f":"Sequential I/O · 顺序 I/O","d":"连续读写相邻的块，比跳来跳去快得多。数据库总想把随机 I/O 换成它。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"随机 I/O","f":"Random I/O · 随机 I/O","d":"读写位置分散、来回跳转，比顺序 I/O 慢得多。磁盘上的算法首先要减少它。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"系统目录","f":"System Catalog · 系统目录","d":"数据库自己的元数据：有哪些表、列、类型、索引。读页时靠它解释字节的含义。","a":["catalog"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"堆文件","f":"Heap File · 堆文件","d":"页的无序集合，元组可以放在任何地方，要靠页目录找到某一页。","a":["Heap File"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"页目录","f":"Page Directory · 页目录","d":"记录每个页在磁盘上的位置和空闲空间，必须持久化。别和内存里的页表搞混。","a":["Page Directory","page directory"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"Slotted Page","f":"Slotted Page · 槽页","d":"页头后是槽数组，元组从页尾往前长。元组可在页内挪动而不影响外部引用，行存的标准布局。","a":["Slotted Pages","slotted page","槽页"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"槽数组","f":"Slot Array · 槽数组","d":"slotted page 里的定长数组，记录每条元组在页内的偏移。有这层间接，元组才能随便挪。","a":["Slot Array","slot array"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"Record ID","f":"Record ID · 记录标识","d":"元组的物理位置，通常是文件、页号加槽号。压实时会变，所以应用不该依赖它。","a":["Tuple ID","Row ID","rowid"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"溢出页","f":"Overflow Page · 溢出页","d":"值太大放不进普通页时单独存放的页，原元组只留指针和长度。","a":["Overflow Page"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"German Strings","f":"German Strings · 德式字符串","d":"元组里除长度和指针外再存一小段前缀，先比前缀，不匹配就不用读溢出页。","a":["德式字符串"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"TOAST","f":"The Oversized-Attribute Storage Technique · 超大属性存储","d":"PostgreSQL 把超大属性移到单独的表并压缩存放的机制。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"double write buffer","f":"Doublewrite Buffer · 双写缓冲区","d":"MySQL 刷脏页时先顺序写进专用缓冲区，再写回原位。防页损坏，也把随机写换成顺序写。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"torn page","f":"Torn Page · 页损坏","d":"数据库页比硬件的原子写单位大，断电时可能只写成一半，页就坏了。","a":["页损坏"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"页表","f":"Page Table · 页表","d":"缓冲池里的哈希表，把页号映射到内存中的帧。只在内存里，不用持久化。","a":["Page Table","page table"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"frame","f":"Frame · 帧","d":"缓冲池切成的定长内存槽，一帧正好放一个页。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"Pin 计数","f":"Pin Count · Pin 计数","d":"记录多少线程正在用这一页。计数大于零就不能淘汰，用完要 unpin。","a":["Pin","pin","pin count","unpin"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"Latch","f":"Latch · 闩","d":"保护内存数据结构的短期互斥手段，防线程把结构改坏。和保护逻辑内容的 Lock 是两回事。","a":["latch","Latching","latching"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"脏页","f":"Dirty Page · 脏页","d":"内存里改过、还没写回磁盘的页，靠页上的脏标记识别，淘汰前必须先写盘。","a":["dirty page","dirty flag","dirty bit","脏标记"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"Evictable","f":"Evictable · 可淘汰","d":"pin 计数降到零的帧，替换器可以考虑换掉。页脏不脏无关，脏页只是要先写盘。","a":["可淘汰"],"h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"替换策略","f":"Replacement Policy · 替换策略","d":"缓冲池满了时决定淘汰哪一页的规则，比如 LRU、CLOCK、ARC。","a":["替换算法","替换器"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"LRU","f":"Least Recently Used · 最近最少使用","d":"淘汰最久没被访问的页。简单，但一次全表扫描就能把热页全冲掉。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"CLOCK","f":"CLOCK · 时钟算法","d":"LRU 的近似：每页一个访问位，指针绕圈清位，碰到 0 就淘汰。开销更小。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"LFU","f":"Least Frequently Used · 最不经常使用","d":"淘汰访问次数最少的页。缺点是老热点计数太高，永远换不出去。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"LRU-K","f":"LRU-K · 看第 K 次最近访问的 LRU","d":"比较每页第 K 次最近访问距今多久，最久的淘汰。能区分偶尔一次和反复访问。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"ARC","f":"Adaptive Replacement Cache · 自适应替换缓存","d":"同时维护最近和频繁两个列表，按访问模式自动调大小，兼顾 LRU 和 LFU 的长处。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"Ghost Cache","f":"Ghost Cache · 幽灵列表","d":"保留已换出页的访问历史，这些页重新读入时不用从零再学。","a":["ghost list","ghost 列表","幽灵列表"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"young/old","f":"Young / Old 区 · MySQL 的近似 LRU-K","d":"MySQL 把 LRU 链表切成两段：新页进 old 区，再被访问才升到 young 区，扫描冲不掉热页。","a":["young 区","old 区"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"顺序泛洪","f":"Sequential Flooding · 顺序泛洪","d":"一次全表扫描读入大量只用一次的页，把缓冲池里的热页全部挤掉。LRU 的致命缺陷。","a":["Sequential Flooding"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"Direct I/O","f":"Direct I/O · 直接 I/O","d":"读写绕过 OS 页缓存，磁盘数据直接进缓冲池，省掉内存里的第二份拷贝。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"Background Writer","f":"Background Writer · 后台写线程","d":"后台把脏页提前写盘、清掉脏标记，这样淘汰时候选页多是干净的。","a":["后台写线程","page cleaning","buffer flushing"],"h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"预取","f":"Prefetching · 预取","d":"提前把接下来要用的页读进内存。数据库知道查询计划，比只会顺序预取的 OS 聪明。","a":["Prefetching"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"页守卫","f":"Page Guard · 页守卫","d":"用 RAII 包住页：出作用域自动 unpin、释放 latch，避免忘记放。","a":["Page Guard"],"h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"缓冲池旁路","f":"Buffer Pool Bypass · 缓冲池旁路","d":"扫描的页直接拷进 worker 自己的内存，不进缓冲池，免得污染它。","a":["Buffer Pool Bypass"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"扫描共享","f":"Scan Sharing · 扫描共享","d":"后来的扫描搭上进行中的扫描，共用读到的页，走完再回头补上开头漏掉的部分。","a":["Scan Sharing","同步扫描","synchronized scans","游标共享"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"元组导向存储","f":"Tuple-Oriented Storage · 元组导向存储","d":"页里存完整元组、原地更新，也就是 slotted page 这条路。对立面是日志结构存储。","a":["Tuple-Oriented","元组导向"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"索引组织存储","f":"Index-Organized Storage · 索引组织存储","d":"让索引本身就是表：B+ 树叶子里直接放元组，查一次索引就拿到数据。","a":["Index-Organized","索引组织"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"日志结构存储","f":"Log-Structured Storage · 日志结构存储","d":"不存元组本身，只追加记录变更，同一元组可能有多份。写快，读要找最新版本。","a":["Log-Structured","日志结构"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"LSM 树","f":"Log-Structured Merge Tree · 日志结构合并树","d":"写入先进内存表，写满后落成不可变的有序文件，后台再合并。写快，读要查多层。","a":["LSM","LSM Tree","日志结构合并树"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"MemTable","f":"MemTable · 内存表","d":"LSM 在内存里的可变有序结构，写入先到这里，写满就刷成 SSTable。","a":["内存表"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"SSTable","f":"Sorted String Table · 有序串表","d":"LSM 落在磁盘上的不可变文件，内部按 key 排序。只能靠压实合并，不能原地改。","a":["Sorted String Table","有序串表"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"压实","f":"Compaction · 压实","d":"重新整理数据让它变紧凑。LSM 里是合并 SSTable 只留最新版本，页内是挪元组填空洞。","a":["Compaction","compaction","页内压实"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"分层压实","f":"Level Compaction · 分层压实","d":"LSM 分多层，第 1 层起 key 范围不重叠。读快，但常要重写整层，写放大严重。","a":["Level Compaction","level compaction"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"通用压实","f":"Universal Compaction · 通用压实","d":"只有一层，挑相邻的 SSTable 局部合并。写放大小、读慢些，适合只查最新数据的时序场景。","a":["Universal Compaction"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"写放大","f":"Write Amplification · 写放大","d":"实际写盘量比用户改的数据多。比如 LSM 里同一份数据每下沉一层就重写一次。","a":["Write Amplification"],"h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"墓碑","f":"Tombstone · 墓碑","d":"不真删，只留一个「已删除」标记。LSM 靠它盖住旧值，线性探测靠它保住探测链。","a":["Tombstone"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"OLTP","f":"Online Transaction Processing · 联机事务处理","d":"大量短小的读写，每次只碰少数几条记录，要求极快。新应用一开始都是这种负载。","a":["联机事务处理"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"OLAP","f":"Online Analytical Processing · 联机分析处理","d":"在积累的海量数据上做分析：跨大量记录、多表连接、聚合，以读为主。","a":["联机分析处理"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"HTAP","f":"Hybrid Transactional/Analytical Processing · 混合事务分析处理","d":"同一份数据既要快速写入，又要能直接分析，不用再导到别的系统。","a":["混合事务分析处理"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"NSM","f":"N-Ary Storage Model · 行存","d":"一条元组的所有属性连续存放。点查和写入方便，适合 OLTP；分析时要读一堆无关列。","a":["N-Ary Storage Model","行存","row store"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"DSM","f":"Decomposition Storage Model · 列存","d":"同一属性的值连续存放，一页只放一列。不读无关列、压缩率高，适合 OLAP。","a":["Decomposition Storage Model","列存","column store"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"PAX","f":"Partition Attributes Across · 跨属性分区","d":"先按行切成块，块内再按列存。有列存的好处，同一元组的属性又不离太远。","a":["Partition Attributes Across"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"Row Group","f":"Row Group · 行组","d":"PAX 里一批元组组成的水平分块，内部每列一个 Column Chunk。Parquet 的术语。","a":["row group","Column Chunk","column chunk"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"隐式偏移","f":"Implicit Offset · 隐式偏移","d":"列存里每列定长，第 i 条元组就在每列第 i 个位置，不用存元组 ID 就能拼回去。","a":["固定长度偏移"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"mod log","f":"Modification Log · 修改日志","d":"MySQL 压缩页里的一小块区域，记录改了什么。盲写时不用解压，写满才解压合并。","h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"RLE","f":"Run-Length Encoding · 游程编码","d":"连续重复的值只存一次加出现次数。排过序效果最好，值交替出现时反而变大。","a":["Run-Length Encoding","游程编码"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"游程","f":"Run · 游程","d":"连续的一段数据。外部排序里指排好序的一段，RLE 里指连续重复的一段值。","h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"Bit Packing","f":"Bit Packing · 位打包","d":"声明的类型往往比实际大，只用够放下值的位数来存。有离群值就不好使。","a":["Bit-packing","位打包"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"Patching","f":"Patching / Mostly Encoding · 补丁编码","d":"大多数值按小位宽存，离群值用哨兵标记，真实值放进单独的补丁表。","a":["Mostly Encoding","Mostly 编码","补丁表"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"位图编码","f":"Bitmap Encoding · 位图编码","d":"每个不同的值配一个位图，第 i 位表示第 i 条元组是否取该值。只适合基数很低的列。","a":["Bitmap Encoding"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"增量编码","f":"Delta Encoding · 增量编码","d":"值彼此接近时存差值而不是绝对值，比如时序数据。差值还能再套一层 RLE。","a":["Delta Encoding","Frame of Reference"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"字典编码","f":"Dictionary Encoding · 字典编码","d":"把频繁出现的值换成定长小整数，另存映射表。列存最常用，可不解压直接比较。","a":["Dictionary Encoding","字典压缩"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"保序字典编码","f":"Order-Preserving Dictionary Encoding · 保序字典编码","d":"字典按原值排序，编码大小关系等于原值大小关系，范围查询能直接在编码上做。","a":["保序字典","保序","order-preserving"],"h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"开放寻址","f":"Open Addressing · 开放寻址","d":"key 的位置不固定，哈希函数只给起点，冲突了就往后找。线性探测属于这一类。","a":["Open Addressing"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"线性探测","f":"Linear Probing · 线性探测","d":"key 冲突时顺着往下找空槽。简单又快，连接里几乎都用它。别和线性哈希搞混。","a":["Linear Probing","Linear Probe Hashing","线性探测哈希"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"布谷鸟哈希","f":"Cuckoo Hashing · 布谷鸟哈希","d":"每个 key 有多个候选位置，都占满就踢走一个让它重新落位。查找 O(1)，实际比线性探测慢。","a":["Cuckoo Hashing"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"链式哈希","f":"Chained Hashing · 链式哈希","d":"每个槽指向一条桶链表，冲突的 key 追加到链尾。链可以无限长，最坏退化成 O(n)。","a":["Chained Hashing"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"可扩展哈希","f":"Extendible Hashing · 可扩展哈希","d":"桶满了就分裂并重分 key，必要时让桶指针数组翻倍，其他桶不动。","a":["Extendible Hashing","Extendible"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"全局深度","f":"Global Depth · 全局深度","d":"可扩展哈希里要看哈希值的几位才能定位桶，决定桶指针数组的大小。","a":["全局位计数器"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"局部深度","f":"Local Depth · 局部深度","d":"可扩展哈希里某个桶实际用了几位。满桶的局部深度等于全局深度时，目录才翻倍。","a":["局部位计数器"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"线性哈希","f":"Linear Hashing · 线性哈希","d":"桶溢出时不分裂它，而是分裂 split pointer 指向的桶，指针依次下移，最终铺匀。","a":["Linear Hashing"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"split pointer","f":"Split Pointer · 分裂指针","d":"线性哈希里指向下一个要分裂的桶。在它上方的桶已分裂过，要用第二个哈希函数。","h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"B+ 树","f":"B+Tree · B+ 树","d":"自平衡的有序多路树，值只在叶子，叶子连成链。查找 O(log n)，是索引的默认选择。","a":["B+树","B+Tree"],"h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"B-Tree","f":"B-Tree · B 树","d":"原始版 B 树，值可以存在任何节点。如今系统说的 B-Tree 几乎都是 B+ 树。","a":["B 树"],"h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"扇出","f":"Fan-out · 扇出","d":"B+ 树节点的出边数，越大树越矮。连接里的扇出则指一行匹配出多行。","a":["fan-out","Fan-out"],"h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"路标","f":"Guide Post · 路标","d":"B+ 树内部节点里的键，只负责指路。看到它不代表这个键存在，要走到叶子才知道。","a":["Guide Post","导航键"],"h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"半满","f":"Half-Full · 半满","d":"B+ 树的不变式：除根外每个节点至少半满，低于它就要借键或合并。","h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"借键","f":"Redistribution · 借键","d":"删除后节点不足半满时，从相邻兄弟借一个键并更新父节点路标。借不了才合并。","a":["重分配"],"h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"聚簇索引","f":"Clustered Index · 聚簇索引","d":"元组的物理顺序和索引顺序一致，沿叶子扫就是顺序 I/O。InnoDB 的主键索引就是。","a":["聚簇","Clustered"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"非聚簇索引","f":"Unclustered Index · 非聚簇索引","d":"索引顺序和元组物理顺序无关，沿索引取元组几乎每条一次随机 I/O。","a":["非聚簇","Unclustered"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"二级索引","f":"Secondary Index · 二级索引","d":"主键索引之外的索引。MySQL 里叶子存主键值，要再回主索引查一次。","h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"跳跃扫描","f":"Skip Scan · 跳跃扫描","d":"复合索引 (A, B) 上只给 B：没有前缀可走，所有叶子都得看，但可以并行扫。","a":["Skip Scan","skip scan"],"h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"后缀截断","f":"Suffix Truncation · 后缀截断","d":"比较时只用键的前缀，截掉后面。前缀不同立刻出结果，相同才比完整的键。","a":["Suffix Truncation","前缀比较"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"过滤器","f":"Filter · 过滤器","d":"只回答「有没有」，不告诉你在哪。常放在索引前面，省掉无谓的查找。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"Bloom Filter","f":"Bloom Filter · 布隆过滤器","d":"用位数组和多个哈希函数判断 key 在不在。说没有就一定没有，说有可能是误报。","a":["Bloom filter","布隆过滤器"],"h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"假阳性","f":"False Positive · 假阳性","d":"说有其实没有。Bloom Filter 允许这种误报，代价只是多查一次。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"假阴性","f":"False Negative · 假阴性","d":"说没有其实有，等于漏了数据。Bloom Filter 绝不允许出现。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"Counting Bloom Filter","f":"Counting Bloom Filter · 计数布隆过滤器","d":"把 Bloom Filter 的位换成计数器，减到 0 才算删掉，因此支持删除。","a":["Counting Bloom"],"h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"Cuckoo Filter","f":"Cuckoo Filter · 布谷鸟过滤器","d":"存 key 的指纹，删除时精确移除指纹，所以支持删除。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"SuRF","f":"Succinct Range Filter · 紧凑范围过滤器","d":"基于紧凑基数树的过滤器，能回答「这个范围内有没有 key」，其他过滤器做不到。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"跳表","f":"Skip List · 跳表","d":"多层有序链表，抛硬币决定节点升几层，查找期望 O(log n)，不用再平衡。MemTable 常用。","a":["Skip List"],"h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"字典树","f":"Trie / Radix Tree · 字典树 / 基数树","d":"每层只存 key 的一小段，路径拼出 key。查找只看 key 长度，第一层就可能判定不存在。","a":["Trie","Radix Tree","基数树"],"h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"倒排索引","f":"Inverted Index · 倒排索引","d":"把「文档→内容」反过来，变成「词→包含它的文档列表」，用来做全文检索。","a":["Inverted Index"],"h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"posting list","f":"Posting List · 倒排列表","d":"倒排索引里一个词对应的记录列表，通常还带词频等信息。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"GIN","f":"Generalized Inverted Index · 通用倒排索引","d":"PostgreSQL 的倒排索引：复用 B+ 树做词典，叶子存 posting list。","a":["Generalized Inverted Index"],"h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"FST","f":"Finite State Transducer · 有限状态转换器","d":"Lucene 的词典结构，像边上带权重的字典树。权重靠全部 key 算出，所以必须不可变。","a":["有限状态转换器"],"h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"BM25","f":"Best Matching 25","d":"经典的文本相关性打分算法。PostgreSQL 自带的只看词频，要用它得装扩展。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"n-gram","f":"n-gram","d":"把文本切成所有连续 n 个字符的片段，让倒排索引能模糊匹配拼错的词。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"ANN","f":"Approximate Nearest Neighbor · 近似最近邻","d":"在向量里找最相近的若干个，允许不绝对精确以换速度。向量索引干的就是这个。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"IVFFlat","f":"Inverted File Flat · 倒排式向量索引","d":"先用 K-means 把向量聚成簇，查询时只在离得最近的几个簇里搜索。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"HNSW","f":"Hierarchical Navigable Small Worlds · 分层可导航小世界图","d":"多层图式向量索引，上层稀疏下层密，从顶层逐层逼近，思路和跳表一样。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"Test-and-Set","f":"Test-and-Set / Compare-and-Swap · 原子指令","d":"原子 CPU 指令：检查内存值，符合预期才改写。自旋 latch 就靠它实现。","a":["Compare-and-Swap","CAS"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"自旋 Latch","f":"Spin Latch · 自旋 Latch","d":"拿不到就在循环里反复重试，不让出 CPU。实现简单，但竞争时白耗 CPU，NUMA 上更糟。","a":["自旋 latch","自旋锁"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"读写 Latch","f":"Reader-Writer Latch · 读写 Latch","d":"读模式可多人同时持有，写模式独占。有写者排队时，新来的读者也要等。","a":["读写 latch","reader-writer latch"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"Latch Crabbing","f":"Latch Crabbing / Latch Coupling · 闩耦合","d":"下行时先拿孩子的 latch，孩子安全才放开上面的，像螃蟹一样交替挪步。","a":["Latch Coupling","latch crabbing","Crabbing","crabbing","闩耦合","螃蟹步"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"乐观 Latch Crabbing","f":"Optimistic Latch Crabbing · 乐观 Latch Crabbing","d":"一路读 latch 下去，到叶子才拿写 latch。赌不用分裂合并，赌错就从根走悲观版。","a":["乐观 latch crabbing","乐观 crabbing","Bayer-Schkolnick"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"安全节点","f":"Safe Node · 安全节点","d":"本次操作不会让它分裂或合并的节点：插入时未满，删除时超过半满。","a":["Safe Node"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"No-Wait","f":"No-Wait · 不等待","d":"拿不到 latch 就立刻放弃、撤销改动、从头重试。不等待就不会死锁。","a":["no-wait"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"外部归并排序","f":"External Merge Sort · 外部归并排序","d":"数据放不进内存时用：先分块排好写盘，再一趟趟归并。尽量走顺序 I/O。","a":["External Merge Sort"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"Top-N 堆排序","f":"Top-N Heap Sort · Top-N 堆排序","d":"查询既排序又限条数时，只用一个容量 N 的堆扫一遍，不用全排。","a":["Top-N"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"双缓冲","f":"Double Buffering · 双缓冲","d":"缓冲区一分为二、乒乓切换：一半在干活，一半在后台做 I/O，把磁盘停顿藏起来。","a":["Double Buffering"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"代码特化","f":"Code Specialization · 代码特化","d":"为具体类型生成专用的比较代码，省掉函数指针调用。C++ 模板、JIT 都能做到。","a":["Code Specialization"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"归一化键","f":"Normalized Keys · 归一化键","d":"把 key 变成定长二进制，字节序等于原值顺序，之后全用 memcmp 比较，很快。","a":["Normalized Keys"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"外部哈希聚合","f":"External Hash Aggregation · 外部哈希聚合","d":"内存放不下时先按哈希分区写盘，再逐个分区读入，用另一个哈希函数建表聚合。","a":["ReHash"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"早期物化","f":"Early Materialization · 早期物化","d":"算子之间传完整元组，上层不用回表。行存常用，代价是管道里搬的数据多。","a":["Early Materialization"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"晚期物化","f":"Late Materialization · 晚期物化","d":"只传 RecordID 和必要的列，用到时才回表取。列存常用，不搬最后要扔的数据。","a":["Late Materialization"],"h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"物化","f":"Materialization · 物化","d":"把中间结果或元组真正算出来存好，而不是只留引用、边算边传。","h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"回表","f":"Table Lookup · 回表","d":"索引或中间结果里没有要的列，只好拿 RecordID 回原表再取一次。","a":["回基表"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"溢写","f":"Spill to Disk · 溢写到磁盘","d":"内存放不下时把中间结果写到磁盘。哈希表溢出尤其糟，探测会变成随机 I/O。","a":["溢出到磁盘"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"外表","f":"Outer / Inner Table · 外表 / 内表","d":"嵌套循环里外层扫的是外表，内层被反复扫的是内表。小表放外层更省 I/O。","a":["内表"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"嵌套循环连接","f":"Nested Loop Join · 嵌套循环连接","d":"外表的每条元组都去内表找匹配。写起来最简单，靠分块或索引才用得上。","a":["Nested Loop Join"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"朴素嵌套循环","f":"Simple Nested Loop Join · 朴素嵌套循环","d":"外表每来一条元组，就把内表每一页重读一遍。成本极高，只作对比的起点。","a":["Simple Nested Loop Join"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"块嵌套循环","f":"Block Nested Loop Join · 块嵌套循环","d":"外表一次读入一批页，这批只扫一遍内表。内存够大时成本降到 M + N。","a":["Block Nested Loop Join","块嵌套循环连接"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"索引嵌套循环","f":"Index Nested Loop Join · 索引嵌套循环","d":"内表上有索引时，外表每条元组直接查索引，不用全扫内表。","a":["Index Nested Loop Join","索引嵌套循环连接"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"排序归并连接","f":"Sort-Merge Join · 排序归并连接","d":"两表先按连接键排序，再用双游标归并匹配。数据本来有序时最合算。","a":["Sort-Merge Join","排序归并"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"哈希连接","f":"Hash Join · 哈希连接","d":"一张表建哈希表，另一张逐条探测，两步不再嵌套。等值连接里通常最快。","a":["Hash Join"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"build 侧","f":"Build / Probe Side · 构建侧 / 探测侧","d":"哈希连接里建哈希表的一边叫 build，拿元组去查的一边叫 probe。","a":["probe 侧"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"Bloom Join","f":"Bloom Join / Sideways Information Passing · 侧向信息传递","d":"build 侧顺手建 Bloom Filter 递给 probe 侧，不匹配的元组直接丢，不用碰哈希表。","a":["Sideways Information Passing","侧向信息传递","半连接优化"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"Grace 哈希连接","f":"Grace Hash Join · 分区哈希连接","d":"哈希表放不下内存时，先把两表按哈希分区写盘，再逐对分区建表探测。","a":["Grace Hash Join","Grace 哈希","GRACE","分区哈希连接","Partitioned Hash Join"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"递归分区","f":"Recursive Partitioning · 递归分区","d":"某个分区还是放不下内存时，换个哈希函数只对它再分一层。","h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"混合哈希连接","f":"Hybrid Hash Join · 混合哈希连接","d":"Grace 的改良：特别热的分区留在内存里直接处理，其余照常写盘。难在提前知道谁热。","a":["Hybrid Hash Join"],"h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"流水线","f":"Pipeline · 流水线","d":"一段连续的算子，元组可不停顿地一路往上流，到阻断算子为止。CPU 的流水线是另一回事。","a":["Pipeline"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"流水线阻断算子","f":"Pipeline Breaker · 流水线阻断算子","d":"必须收齐全部输入才能吐出结果的算子，比如排序、聚合、哈希连接的 build。","a":["Pipeline Breaker","流水线阻断"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"火山模型","f":"Iterator / Volcano Model · 迭代器模型","d":"每个算子实现 next()，一次交一条元组，从根往下调。简单通用，但函数调用开销大。","a":["迭代器模型","Volcano Model","Volcano","Iterator","火山"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"物化模型","f":"Materialization Model · 物化模型","d":"算子一次把全部结果交给上层。OLTP 上合理；LIMIT 时要搬大量用不上的元组。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"向量化模型","f":"Vectorized / Batch Model · 向量化模型","d":"算子一次传一批元组，摊薄函数调用，还能用 SIMD。现代 OLAP 系统的标配。","a":["向量化","批模型","Vectorized","vectorized model","Batch Model"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"算子融合","f":"Operator Fusion · 算子融合","d":"把上层逻辑塞进下层算子，比如边扫描边过滤。只能在同一条流水线内做。","a":["Operator Fusion"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"拉模型","f":"Pull-Based · 拉模型","d":"根节点调 next() 把数据一层层拉上来，控制流和数据流混在一起。实现容易，是主流。","a":["Pull-Based"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"推模型","f":"Push-Based · 推模型","d":"没有 next()，由调度器安排流水线任务，数据自下而上推。控制流和数据流分离。","a":["Push-Based"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"多索引扫描","f":"Multi-Index Scan · 多索引扫描","d":"同时探测多个索引，把 RecordID 集合求交或并，再去取元组。PostgreSQL 叫 Bitmap Scan。","a":["Multi-Index Scan","Bitmap Scan","位图扫描","Index Merge","索引归并"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"DAG","f":"Directed Acyclic Graph · 有向无环图","d":"没有环的有向图。查询计划本质是算子的 DAG，多数系统实现成树。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"物化视图","f":"Materialized View · 物化视图","d":"预先算好并存下来的查询结果。高端系统能增量更新，PostgreSQL 要手动刷新。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"Zone Map","f":"Zone Map / Small Materialized Aggregates · 区域图","d":"给一块数据预先算好 MIN、MAX 等摘要，看摘要就知道这块不用读。是过滤器不是索引。","a":["Zone map","zone map","区域图","SMA","Small Materialized Aggregates"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"万圣节问题","f":"Halloween Problem · 万圣节问题","d":"更新让元组在扫描路径上挪了位置，同一条逻辑元组被看到多次、反复修改。","a":["Halloween Problem"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"JIT","f":"Just-In-Time Compilation · 即时编译","d":"运行时把表达式或整个计划编译成机器码，省掉遍历表达式树的开销。","a":["JIT 编译"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"Prepared Statement","f":"Prepared Statement · 预编译语句","d":"查询只编译一次、缓存计划，之后带参数反复执行。风险是计划不一定适合每个参数。","a":["prepared statement"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"常量折叠","f":"Constant Folding · 常量折叠","d":"能提前算出的常量表达式只算一次，把结果当常量塞回去。","a":["Constant Folding"],"h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"worker","f":"Worker · 工作单元","d":"数据库里的计算单元，可以是进程或线程，执行查询或压实这类后台任务。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"进程模型","f":"Process per Worker · 每 worker 一个进程","d":"系统怎么组织 worker。狭义指每个 worker 一个 OS 进程，靠共享内存通信，PostgreSQL 如此。","a":["Process per Worker"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"线程模型","f":"Thread per Worker · 每 worker 一个线程","d":"一个进程里多线程当 worker，共享地址空间、开销小，但一个线程崩了整个进程全挂。","a":["Thread per Worker"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"查询间并行","f":"Inter-Query Parallelism · 查询间并行","d":"不同查询在不同 worker 上同时跑。单个查询本身不一定并行。","a":["Inter-Query Parallelism","Inter-Query"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"查询内并行","f":"Intra-Query Parallelism · 查询内并行","d":"一个查询内部用多个 worker，分算子内、算子间和浓密三种形态。","a":["Intra-Query Parallelism","Intra-Query"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"算子内并行","f":"Intra-Operator Parallelism · 算子内并行","d":"多个 worker 跑同一段流水线，各处理一部分数据。最常见的并行方式。","a":["Intra-Operator","水平并行"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"算子间并行","f":"Inter-Operator Parallelism · 算子间并行","d":"多个 worker 同时跑计划的不同部分，上游边出下游边接。比融合贵，换来并行度。","a":["Inter-Operator","垂直并行"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"浓密并行","f":"Bushy Parallelism · 浓密并行","d":"算子内和算子间并行同时上，只有少数高端企业系统支持。","a":["Bushy Parallelism","Bushy"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"浓密连接树","f":"Bushy Join Tree · 浓密连接树","d":"连接树两侧都可以是子连接的结果。搜索空间太大，大多数优化器不生成。","a":["Bushy Join Tree","浓密树"],"h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"Exchange 算子","f":"Exchange Operator · 交换算子","d":"在 worker 之间传数据的算子：Gather 多合一，Distribute 一分多，Repartition 多到多。","a":["Exchange","Exchange Operator","交换算子","Gather","Distribute","Repartition"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"RAID 0","f":"RAID 0 · 条带化","d":"页轮流写到不同的盘。读写都能并行，但丢一块盘就丢一部分数据。","a":["条带化","Striping"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"RAID 1","f":"RAID 1 · 镜像","d":"每页在每块盘上都存一份。读能并行、完全冗余，但写要等所有盘成功。","a":["Mirroring","RAID 1 镜像"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"垂直分区","f":"Vertical Partitioning · 垂直分区","d":"按列把表切开分别存放。列存 DSM 就是一种垂直分区。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"UDF","f":"User-Defined Function · 用户自定义函数","d":"用户自己写、在 SQL 里调用的函数。可能很贵，下推时要小心。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"绑定器","f":"Binder · 绑定器","d":"把 SQL 里的表名、列名换成内部对象 ID，顺便拿到类型和 schema，找不到就报错。","h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"逻辑计划","f":"Logical Plan · 逻辑计划","d":"只说要做什么，比如访问哪张表、做什么聚合，不说用什么算法。","h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"物理计划","f":"Physical Plan · 物理计划","d":"说清具体怎么执行：用哈希连接还是排序归并、走哪个索引。","h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"物理属性","f":"Physical Property · 物理属性","d":"数据的物理特征，最典型的是排序顺序。优化器不跟踪就可能满足不了 ORDER BY。","h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"谓词下推","f":"Predicate Pushdown · 谓词下推","d":"把过滤条件挪到计划下层先做，少搬元组。通常更快，谓词很贵时不一定。","a":["Predicate Pushdown"],"h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"投影下推","f":"Projection Pushdown · 投影下推","d":"在连接等操作之前就把用不到的列扔掉，少搬数据。","a":["Projection Pushdown"],"h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"启发式优化器","f":"Heuristic / Rule-Based Optimizer · 启发式优化器","d":"只应用固定规则，不用成本模型。简单好调试，但连接超过两张表就不行。","a":["规则优化器"],"h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"魔法常数","f":"Magic Constant · 魔法常数","d":"硬编码的经验数字，比如顺序扫描比随机 I/O 快几倍。换了硬件或数据就可能不对。","h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"Hints","f":"Query Hints · 查询提示","d":"写在 SQL 里指挥优化器用哪个索引或连接顺序。等于把计划写死，数据变了就过时。","h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"Sargable","f":"Search ARGument ABLE · 可作搜索参数的","d":"谓词能被索引用上。这样优化器才能把逻辑扫描换成索引扫描。","a":["sargable"],"h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"左深树","f":"Left-Deep Tree · 左深树","d":"先连两张表，结果再逐张往上连的连接树形状。System R 只搜它，砍掉大量搜索空间。","a":["Left-Deep Tree","Left-Deep"],"h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"合取","f":"Conjunction · 合取","d":"用 AND 连接的条件。优化器先把它拆成独立谓词，才能分别下推。","a":["合取子句","合取分解"],"h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"Cascades","f":"Cascades Optimizer Framework · Cascades 优化器框架","d":"自顶向下的优化器框架，做分支限界搜索，物理属性从一开始就写进搜索目标。","h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"记忆化表","f":"Memo Table · 记忆化表","d":"Cascades 里记下已算过成本的子问题，重复访问时直接查表。","a":["Memo Table","memo 表"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"强制器节点","f":"Enforcer Node · 强制器节点","d":"专门插进计划、保证数据满足某物理属性的算子，比如为满足有序要求加的排序。","a":["Enforcer Node","Enforcer","强制器"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"GEQO","f":"Genetic Query Optimizer · 遗传查询优化器","d":"PostgreSQL 在连接的表很多时放弃动态规划，改用遗传算法随机搜索，不保证结果好。","a":["遗传算法"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"基数估算","f":"Cardinality Estimation · 基数估算","d":"预测每个算子输出多少条元组。优化器选计划全靠它，连接越多错得越离谱。","a":["连接基数"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"基数","f":"Cardinality · 基数","d":"个数。列的基数指不同值的个数，算子的基数指它输出多少条元组。","a":["cardinality"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"选择性","f":"Selectivity · 选择性","d":"一条元组满足谓词的概率。说条件很有选择性，是指它能筛掉绝大多数元组。","a":["selectivity"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"成本模型","f":"Cost Model · 成本模型","d":"给计划打分的内部模型，不预测实际耗时，只判断 A 是否比 B 好，不能跨系统比。","a":["Cost Model"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"物理成本","f":"Physical Cost · 物理成本","d":"算子消耗的资源，如磁盘 I/O、网络包、CPU 周期，依赖具体硬件。","a":["Physical Cost"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"逻辑成本","f":"Logical Cost · 逻辑成本","d":"算子输出多少条元组，与用哪种物理算子无关，所以能提前用来剪枝。","a":["Logical Cost"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"ANALYZE","f":"ANALYZE 命令","d":"收集表的统计信息，如不同值个数、直方图，供优化器估算。会把旧的整个重算。","h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"直方图","f":"Histogram · 直方图","d":"记录每个值或每段值出现多少次的统计结构，优化器最常用的估算依据。","a":["Histogram"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"等宽直方图","f":"Equi-Width Histogram · 等宽直方图","d":"每个桶的值域宽度相同。简单，但高频值会和低频值混在一个桶里。","a":["Equi-Width"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"等深直方图","f":"Equi-Depth Histogram · 等深直方图","d":"每个桶的计数相同，宽度自适应，高频值不容易淹没低频值。比等宽更好。","a":["Equi-Depth"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"N 偏直方图","f":"N-Biased Histogram · N 偏直方图","d":"为最频繁的值（重击者）各存精确计数，其余值扔进一个桶，只留粗略计数。","a":["N-Biased","重击者","heavy hitters"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"MCV","f":"Most Common Values · 最常见值","d":"一列里出现最多的值。PostgreSQL 的统计信息里单独存它们及其频率。","h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"Sketch","f":"Sketch · 概览","d":"概率型数据结构，用很小的空间近似回答频次、不同值个数这类问题，容易合并。","a":["sketch","概览"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"Count-Min Sketch","f":"Count-Min Sketch","d":"估算元素频次的 Sketch，能回答哪些元素最频繁。Project 0 写过它。","h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"HyperLogLog","f":"HyperLogLog","d":"估算一列有多少个不同值的 Sketch。","h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"相关列统计","f":"Correlated Statistics · 相关列统计","d":"为相关的多列建联合统计，比如邮编和城市，避免当成独立变量估错。","a":["Correlated Statistics"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"独立性假设","f":"Independence Assumption · 独立性假设","d":"假设多个谓词互不相关，选择性直接相乘。遇到相关列会严重低估。","a":["谓词独立"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"包含原则","f":"Containment Principle · 包含原则","d":"估连接时假设内表的键总能在外表里找到匹配，否则公式写不出来。","a":["Containment Principle"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"Join Order Benchmark","f":"Join Order Benchmark · 连接顺序基准","d":"用 IMDb 真实数据测优化器的基准，暴露了各系统基数估算错得多厉害。","h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"自适应查询处理","f":"Adaptive Query Processing · 自适应查询处理","d":"运行中发现估计错了就换算子或重新规划。只有少数高端系统做。","a":["Adaptive Query Processing","AQP"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"Andy Pavlo","f":"本课主讲教授","d":"CMU 数据库方向的副教授，15-445 的主讲老师。笔记里的观点和段子大多出自他。","h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"Jim Gray","f":"事务理论的奠基人，图灵奖得主","d":"在 IBM System R 项目中研究事务与锁，参与提出 2PL，五分钟法则和弹珠写偏斜也出自他。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"Ted Codd","f":"关系模型的发明人，图灵奖得主","d":"提出关系模型和关系代数，奠定了现代数据库的基础。OLAP 这个词也是他造的。","a":["Codd"],"h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"Charles Bachman","f":"网状数据库的先驱，图灵奖得主","d":"主导 IDS，是 CODASYL 网状模型的代表人物，主张程序员沿着指针在数据里导航。","h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"Michael Stonebraker","f":"Ingres 和 Postgres 的缔造者，图灵奖得主","d":"在伯克利先后做出 Ingres 和 Postgres，还写过 shared-nothing 论文、提出 3PC。","a":["Stonebraker"],"h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"Leslie Lamport","f":"Paxos 的发明人，图灵奖得主","d":"分布式系统大师。Paxos 论文用考古故事包装，当年被拒，多年后才正式发表。","a":["Lamport"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"Goetz Graefe","f":"Volcano 和 Cascades 的作者","d":"还提出了 Exchange 算子，写过 B+ 树技术专著，课上的 lock/latch 对照表也出自他。","a":["Graefe"],"h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"Rudolf Bayer","f":"B 树的发明人之一","d":"在波音与 McCreight 提出 B 树，后来又和 Schkolnick 提出乐观的 latch crabbing。","a":["Bayer"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"Phil Lehman","f":"B-link 树的第一作者","d":"在 CMU 提出 B-link 树，它加入的兄弟指针成了现代 B+ 树的标配。","a":["Lehman"],"h":"../ch03-indexes.html#L08","n":"详见 #08 B+ 树"},{"t":"Guido Moerkotte","f":"Zone Map（SMA）论文的作者","d":"德国数据库学者，Thomas Neumann 的博士导师。Zone Map 的思路出自他的 SMA 论文。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"Thomas Neumann","f":"HyPer 和 Umbra 的主要作者","d":"慕尼黑的数据库学者，Andy 口中的「头号德国人」，以查询优化和代码生成著称。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"H. T. Kung","f":"OCC 的发明人","d":"在 CMU 提出乐观并发控制。有趣的是他本行不是数据库，而是做网络的。","a":["H.T. Kung","Kung"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"Larry Ellison","f":"Oracle 创始人","d":"照着 IBM 的做法做出 Oracle。课上讲了他把糟糕的优化器包装成「语义优化器」的故事。","a":["Ellison"],"h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"Linus Torvalds","f":"Linux 内核的作者","d":"曾在邮件列表上痛批用户态自旋锁。数据库大多不照做，因为不想让线程被内核挂起。","a":["Linus"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"Jignesh Patel","f":"CMU 数据库方向教授","d":"CMU 另一位教数据库的教授，David DeWitt 的博士生。"},{"t":"David DeWitt","f":"数据库领域的资深学者","d":"Jignesh Patel 的博士导师，Hybrid 哈希连接的发明人之一，曾直言微软买下的假列存是垃圾。","h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"Jeff Dean","f":"Google 的顶尖工程师","d":"课上的硬件延迟表源自他的经典版本，Andy 也拿他当顶尖工程师的代名词。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"Andreas Reuter","f":"ACID 缩写的提出者之一","d":"和 Theo Härder 合写论文造出 ACID，又和 Jim Gray 合著那本讲事务的经典教材。","a":["Reuter"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"Dave Andersen","f":"CMU 教授","d":"他和学生发明了 Cuckoo Filter，团队写出了最好的开源布谷鸟哈希，SuRF 也出自他的学生。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"Marcin Żukowski","f":"Snowflake 联合创始人","d":"在 CWI 做 VectorWise 时提出向量化执行的核心思路，这套做法后来成了业界标准。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"PostgreSQL","f":"由 Stonebraker 的 Postgres 发展而来的开源关系数据库","d":"课上最常拿来举例的系统：进程模型、追加式 MVCC，要靠 VACUUM 清理旧版本。","a":["Postgres","PG"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"MySQL","f":"最流行的开源关系数据库之一","d":"默认引擎 InnoDB，默认隔离级别 REPEATABLE READ，增量式 MVCC，二级索引存主键。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"InnoDB","f":"MySQL 的默认存储引擎","d":"索引组织存储（聚簇索引），默认页 16 KB，缓冲池用 young/old 两区近似 LRU-K。","h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"SQLite","f":"嵌入式关系数据库","d":"不用服务器，以库的形式嵌进应用，整个数据库就是一个文件。单写者多读者。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"Oracle","f":"甲骨文公司的商业关系数据库","d":"Zone Map 一词出自它。默认 READ COMMITTED，要 SERIALIZABLE 时实际给的是更弱的级别。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"SQL Server","f":"微软的商业关系数据库","d":"优化器按 Cascades 风格重写，Andy 评价极高。默认隔离级别 READ COMMITTED。","h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"DB2","f":"IBM 的商业关系数据库","d":"把 System R 的研究成果做成产品，让 SQL 成了事实标准。游标稳定性就是它的隔离级别。","h":"../ch01-foundations.html#L02","n":"详见 #02 现代 SQL"},{"t":"System R","f":"IBM 早期的关系数据库原型","d":"第一个基于成本的查询优化器出自这里，SEQUEL 语言和 2PL 也是。","h":"../ch05-optimization.html#L15","n":"详见 #15 查询优化 I：变换规则与搜索策略"},{"t":"Ingres","f":"Stonebraker 在伯克利做的关系数据库","d":"和 System R 同期的早期关系系统，用 QUEL 语言。PostgreSQL 的名字就是 Post-Ingres。","a":["INGRES"],"h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"IMS","f":"Information Management System · IBM 的层次数据库","d":"为阿波罗登月造的，数据按树形组织、逻辑和存储绑死。至今还在银行里运行。","h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"CODASYL","f":"Conference on Data Systems Languages","d":"网状数据模型的标准组织。程序员沿指针逐条导航，和 Codd 的关系模型有过一场大论战。","h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"DuckDB","f":"嵌入式分析型数据库","d":"列存加向量化，以库的形式运行，语法沿用 PostgreSQL。HW1 就用它写 SQL。","h":"../homework.html#HW1","n":"详见 HW1 HW1：SQL 查询"},{"t":"ClickHouse","f":"开源列式分析数据库，出自 Yandex","d":"查询极快，靠向量化和专用代码，光哈希表就有 24 种实现。连接重排序是短板。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"HyPer","f":"慕尼黑工业大学的数据库系统","d":"最早做推模型和 LLVM 查询编译的系统之一。DuckDB 的优化器抄的就是它。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"Umbra","f":"HyPer 的二代","d":"自底向上优化器公认最好。两段式 JIT：先跑汇编，后台用 LLVM 编译好再热替换。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"CedarDB","f":"Umbra 的商业版","d":"把 Umbra 这条研究线做成产品的数据库，技术上和 Umbra 一脉相承。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"Vertica","f":"早期的商业列存数据库","d":"最早做列存加晚期物化的系统之一，后来改从 S3 读数据时认定这是错误，把它去掉了。","h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"MonetDB","f":"荷兰 CWI 的列存数据库","d":"物化模型的首创者：算子一次把全部结果交给上层。VectorWise 就是为改进它而生的。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"VectorWise","f":"出自 CWI 的向量化分析引擎","d":"向量化执行和预编译原语的源头，后被 Ingres 买下，作者随后参与创办 Snowflake。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"Snowflake","f":"云数据仓库","d":"选择 shared-disk，把存储交给 S3、工程投在计算上，执行走向量化和预编译原语。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"Redshift","f":"Amazon Redshift · AWS 的云数据仓库","d":"现代 OLAP 系统之一，列存加向量化执行。课上提到它的 mostly8 编码。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"BigQuery","f":"Google 的云数据仓库","d":"内部引擎是 Dremel。把 shuffle 当成中间检查点，查询中途也能增减节点。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"Teradata","f":"老牌商业数据仓库","d":"课上常和 Oracle、DB2 并列，代表昂贵的商业系统，也卖软硬一体的数据库一体机。","h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"Databricks","f":"云数据平台公司","d":"产品基于 Spark，自研了 Photon 引擎，Delta Lake 也由它主导。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"Photon","f":"Databricks 的 C++ 查询引擎","d":"通过 JNI 接进 JVM 上的 Spark，靠向量化和预编译原语取代了原来的 JIT 路线。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"Yellowbrick","f":"商业数据仓库","d":"以极端著称：自写内核驱动和 UDP 协议，用 DPDK 绕过内核，启动后不再和 OS 打交道。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"Firebolt","f":"云数据仓库","d":"最初是 ClickHouse 的一个 fork，第 18 讲的客座来自这里。","h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"MotherDuck","f":"DuckDB 的商业化公司之一","d":"第 11 讲的客座。主打双端执行：一条查询拆成本地和云端两部分来跑。","h":"../ch04-execution.html#L11","n":"详见 #11 排序与聚合算法"},{"t":"SpiralDB","f":"Vortex 文件格式背后的公司","d":"第 14 讲的客座，主张字节在 S3 上的排列方式决定了性能。","a":["Spiral"],"h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"Vortex","f":"SpiralDB 的列式文件格式","d":"目标是替代 Parquet，随机访问和扫描都更快，可以直接从 DuckDB 里查询。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"DataFusion","f":"Apache 的可嵌入查询引擎","d":"现代向量化引擎的一员，走推模型；早期是向量化加拉模型。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"RelationalAI","f":"第 25 讲的客座公司","d":"在做 Rel 语言，想用小而语义清晰的核心语言修掉 SQL 的问题。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"dbt","f":"data build tool · 数据转换工具","d":"用 SQL 加 Jinja 模板写数据管道，把查询下推到数据仓库里执行。第 2 讲的客座。","h":"../ch01-foundations.html#L02","n":"详见 #02 现代 SQL"},{"t":"Spanner","f":"Google 的全球分布式数据库","d":"用原子钟同步时间，是极少数支持外部一致性的系统。它的论文承认了事务不可或缺。","h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"DynamoDB","f":"亚马逊的云托管键值数据库","d":"课上提到它的确定性调度和侦察事务：先假跑一遍不改数据，提交时再跑一遍比对。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"CockroachDB","f":"分布式 SQL 数据库","d":"少数默认可串行化的系统之一，优化器走 Cascades 路线。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"YugabyteDB","f":"兼容 PostgreSQL 的分布式数据库","d":"直接复用 PostgreSQL 源码改造而成，开源。第 7 讲的客座。","a":["Yugabyte"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"TiDB","f":"PingCAP 的分布式数据库","d":"课上把它和 SingleStore 并列为 HTAP 的代表。","h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"SingleStore","f":"HTAP 数据库","d":"最初是内存数据库，后来改了架构。第 5 讲的客座。","h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"Neon","f":"云上的 PostgreSQL 服务","d":"创始人也是 SingleStore 的创始人，后被 Databricks 收购。","h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"Cassandra","f":"Apache 的分布式 NoSQL 数据库","d":"存储用 LSM 树，分片用一致性哈希。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"HBase","f":"Hadoop 生态的分布式 NoSQL 数据库","d":"跑在 HDFS 上，底层是 LSM 树。","h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"MongoDB","f":"文档数据库","d":"NoSQL 的代表。早期没有缓冲池，直接用 mmap，后来全部砍掉，收购了 WiredTiger。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"Redis","f":"内存键值存储","d":"常用作缓存。命令在单线程上执行，所以天然原子，几乎不用操心并发控制。","h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"RocksDB","f":"Facebook 基于 LevelDB 开发的嵌入式键值存储","d":"LSM 树的代表实现，被很多数据库当存储引擎。","h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"LevelDB","f":"Google 开源的嵌入式键值存储","d":"LSM 树的经典实现，RocksDB 就是从它 fork 出来的。","h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"WiredTiger","f":"MongoDB 的存储引擎","d":"MongoDB 收购后用来替换 mmap 方案。主体是标准缓冲池，mmap 只用在极小的场景。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"LMDB","f":"Lightning Memory-Mapped Database","d":"嵌入式键值库，基于 mmap 和影子分页，作者的理念和 Andy 正好相反。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"Berkeley DB","f":"嵌入式键值存储库","d":"里面实现了线性哈希，后被 Oracle 收购。","h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"Parquet","f":"Apache Parquet · 列式文件格式","d":"数据湖的事实标准，按 row group 分块，footer 里放元数据。正被一批新格式挑战。","h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"ORC","f":"Optimized Row Columnar","d":"Hadoop 生态里的列式文件格式，和 Parquet 同类。","h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"Iceberg","f":"Apache Iceberg · 开放表格式","d":"在 Parquet 这类文件之上维护表的元数据，让数据湖里的一堆文件能当一张表用。","h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"Delta Lake","f":"Databricks 主导的开放表格式","d":"作用和 Iceberg 类似：在数据湖文件上加事务日志，让它具备表的能力。","h":"../ch02-storage.html#L06","n":"详见 #06 列存数据库与压缩"},{"t":"MapReduce","f":"Google 提出的分布式批处理模型","d":"分 Map 和 Reduce 两步，中间靠 shuffle 搬数据。这件事数据库其实更早就在做。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"Hadoop","f":"Apache 的开源大数据平台","d":"由 HDFS 和 MapReduce 等组成，是大数据和 NoSQL 那一波的代表。"},{"t":"HDFS","f":"Hadoop Distributed File System · Hadoop 分布式文件系统","d":"文件只能追加、不能原地修改，这类存储正是 LSM 树的用武之地。","h":"../ch02-storage.html#L05","n":"详见 #05 日志结构存储（含缓冲池三大优化）"},{"t":"Spark","f":"Apache Spark · 分布式计算引擎","d":"用 Scala 写、跑在 JVM 上，本质是一次一条元组的行式系统。Databricks 的产品基于它。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"S3","f":"Amazon Simple Storage Service · 亚马逊对象存储","d":"容量近乎无限、吞吐高、延迟大，按请求收费。现代云数据库常把它当共享磁盘。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"Lucene","f":"Java 写的全文检索库","d":"倒排索引的代表实现，词典用 FST 存储，Elasticsearch 就建在它之上。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"pgvector","f":"PostgreSQL 的向量索引扩展","d":"支持 IVFFlat 和 HNSW。Andy 认为 90% 的场景用它就够了。","h":"../ch03-indexes.html#L09","n":"详见 #09 过滤器、跳表、字典树、倒排索引与向量索引"},{"t":"IBM","f":"International Business Machines","d":"60–80 年代的计算机业巨头，IMS、System R、DB2 和 SQL 都出自这里。","h":"../ch01-foundations.html#L02","n":"详见 #02 现代 SQL"},{"t":"CWI","f":"Centrum Wiskunde & Informatica · 荷兰国家数学与计算机科学研究中心","d":"MonetDB、VectorWise 和 DuckDB 都出自这里。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"TUM","f":"Technical University of Munich · 慕尼黑工业大学","d":"HyPer 和 Umbra 的出处，课上说的「德国人」主要指这里的数据库团队。","h":"../ch05-optimization.html#L16","n":"详见 #16 查询优化 II：搜索策略、统计信息与成本模型"},{"t":"SQL","f":"Structured Query Language · 结构化查询语言","d":"关系数据库的标准查询语言，声明式：只说要什么，不说怎么取。前身是 IBM 的 SEQUEL。","h":"../ch01-foundations.html#L02","n":"详见 #02 现代 SQL"},{"t":"DBMS","f":"Database Management System · 数据库管理系统","d":"定义、存储、查询和管理数据库的软件。数据库是数据，DBMS 是管它的系统。","h":"../ch01-foundations.html#L01","n":"详见 #01 关系模型与关系代数"},{"t":"OS","f":"Operating System · 操作系统","d":"全课主线之一：数据库比 OS 更了解自己的负载，所以很多事不交给它做。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"CPU","f":"Central Processing Unit · 中央处理器","d":"内存够大时，分析查询的瓶颈就在这里，所以现代引擎追求缓存友好、少分支、少函数调用。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"GPU","f":"Graphics Processing Unit · 图形处理器","d":"擅长大批量并行计算。GPU 数据库试了十几年，卡在整个数据库得塞进显存。","h":"../ch04-execution.html#L12","n":"详见 #12 连接算法：嵌套循环、排序归并、哈希"},{"t":"SSD","f":"Solid State Drive · 固态硬盘","d":"闪存做的非易失存储，比 DRAM 慢两个数量级，但比机械硬盘快得多。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"HDD","f":"Hard Disk Drive · 机械硬盘","d":"靠磁头移动寻道，所以随机 I/O 比顺序 I/O 慢得多。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"NVMe","f":"Non-Volatile Memory Express","d":"走 PCIe 总线的高速 SSD 接口，课上说的本地超快盘就是它。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"DRAM","f":"Dynamic Random Access Memory · 动态随机存取存储器","d":"就是内存：掉电丢数据，课上统一叫 memory，缓冲池就放在这里。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"RAID","f":"Redundant Array of Independent Disks · 独立磁盘冗余阵列","d":"把多块盘组合使用。RAID 0 条带化提速，RAID 1 镜像做冗余。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"FPGA","f":"Field-Programmable Gate Array · 现场可编程门阵列","d":"可以重新编程的硬件芯片。BigQuery 用它做内存 shuffle。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"PCIe","f":"PCI Express","d":"CPU 和网卡、SSD、GPU 之间的高速总线。如今网卡带宽已经超过了它。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"NUMA","f":"Non-Uniform Memory Access · 非一致内存访问","d":"多路 CPU 的机器上，访问离自己近的内存快、远的慢。自旋 latch 在这种机器上尤其糟糕。","h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"IPC","f":"Inter-Process Communication · 进程间通信","d":"进程之间传数据的办法，如管道、信号、共享内存。进程模型的 worker 靠它协作。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"I/O","f":"Input/Output · 输入输出","d":"数据在内存和外部设备之间传输。本课多指读写磁盘，是传统数据库成本的主要来源。","h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"API","f":"Application Programming Interface · 应用程序接口","d":"程序之间约定好的调用方式。"},{"t":"POSIX","f":"Portable Operating System Interface · 可移植操作系统接口","d":"Unix 系统的接口标准，pthread 的 P 就是它。标准定下来之前，各家 Unix 的线程库互不兼容。","h":"../ch04-execution.html#L14","n":"详见 #14 并行查询执行：进程模型、并行度与 I/O 并行"},{"t":"DPDK","f":"Data Plane Development Kit","d":"让程序绕过内核直接收发网络包的工具集。Yellowbrick 用它做内核旁路。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"SPDK","f":"Storage Performance Development Kit","d":"让程序绕过内核直接访问 NVMe 盘的工具集，和 DPDK 是一类技术。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"RDMA","f":"Remote Direct Memory Access · 远程直接内存访问","d":"网卡直接读写另一台机器的内存，不经过对方的 CPU 和内核，需要专用硬件。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"LLVM","f":"开源编译器基础设施","d":"数据库做 JIT 时常先生成 LLVM IR，再交给它编译成机器码，HyPer、PostgreSQL 都这样。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"IR","f":"Intermediate Representation · 中间表示","d":"编译器内部介于源码和机器码之间的代码形式。数据库做 JIT 时常先生成 IR 再编译。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"JVM","f":"Java Virtual Machine · Java 虚拟机","d":"运行 Java、Scala 字节码的虚拟机。Spark 跑在上面，Andy 对它评价很低。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"JNI","f":"Java Native Interface","d":"JVM 里调用 C/C++ 代码的接口。Photon 靠它把 C++ 引擎接进 Spark。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"SIMD","f":"Single Instruction, Multiple Data · 单指令多数据","d":"一条 CPU 指令同时处理多个数据，是向量化执行提速的关键。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"AVX-512","f":"Advanced Vector Extensions · x86 的 SIMD 指令集","d":"AVX2 是 256 位，AVX-512 是 512 位。老 CPU 跑 AVX-512 会降频，可能反而更慢。","a":["AVX2"],"h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"GDB","f":"GNU Debugger · GNU 调试器","d":"命令行调试器：打断点、单步、看变量。P2 调 B+ 树时用得最多。","a":["gdb"],"h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"AddressSanitizer","f":"编译器内置的内存错误检测工具","d":"运行时抓用后释放、越界访问。BusTub 的 Debug 构建默认开启。","a":["ASan"],"h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"ThreadSanitizer","f":"编译器内置的数据竞争检测工具","d":"运行时检测多线程数据竞争。BusTub 用 -DBUSTUB_SANITIZER=thread 打开。","a":["tsan"],"h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"clang-tidy","f":"C++ 静态检查工具","d":"检查代码风格和常见错误。Project 提交前必须跑过，不通过就没有分。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"clang-format","f":"C++ 代码格式化工具","d":"按统一风格自动排版，BusTub 用 make format 调用。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"Clang","f":"LLVM 项目的 C/C++ 编译器","d":"BusTub 推荐用它开发，CMake 检测到别的编译器时会给出警告。","a":["clang"],"h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"GCC","f":"GNU Compiler Collection · GNU 编译器套件","d":"最常用的开源 C/C++ 编译器。早期的查询代码生成就是生成 C 再交给它编译。","h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"CMake","f":"跨平台构建配置工具","d":"读 CMakeLists.txt 生成 Makefile。BusTub 用它配置编译选项，再用 make 构建。","a":["cmake"],"h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"Docker","f":"容器工具","d":"把运行环境打包成镜像。Windows 上做 BusTub 最省事的办法之一。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"WSL","f":"Windows Subsystem for Linux","d":"在 Windows 里运行 Linux 的子系统。BusTub 官方 README 写明不支持它。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"gtest","f":"GoogleTest · Google 的 C++ 单元测试框架","d":"BusTub 的单元测试用它写。名字带 DISABLED_ 的用例默认跳过。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"sqllogictest","f":"用脚本测试 SQL 的工具","d":"测试写在 .slt 文件里：执行 SQL 并比对输出。BusTub 用它测 P3 的执行器。","a":["SQLLogicTest"],"h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"Gradescope","f":"在线作业提交和自动评分平台","d":"Project 提交到这里，用隐藏测试评分。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"mmap","f":"Memory-Mapped File · 内存映射文件","d":"把文件映射进进程地址空间，由 OS 负责换页。Andy 的红线：数据库里永远不要用它。","h":"../ch02-storage.html#L04","n":"详见 #04 内存管理与缓冲池"},{"t":"fsync","f":"把文件的脏数据强制刷到磁盘的系统调用","d":"返回后数据才算真正落盘。它很慢，所以 WAL 用组提交让多个事务共用一次。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"futex","f":"Fast Userspace Mutex · 快速用户态互斥锁","d":"Linux 的锁机制：先在用户态试，抢不到再进内核睡眠。std::mutex 底下就是它。","h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"RAII","f":"Resource Acquisition Is Initialization · 资源获取即初始化","d":"构造时拿资源，析构时自动释放。BusTub 的页守卫靠它保证不忘记放锁和 unpin。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"STL","f":"Standard Template Library · C++ 标准模板库","d":"vector、unordered_map 这些容器和算法。数据库内部常自己写，因为它们不受缓冲池管理。","h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"std::optional","f":"C++17 · 可能没有值的类型","d":"要么装着一个值，要么是空的。CheckedReadPage 失败时就返回空，而不是抛异常。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"std::nullopt","f":"std::optional 的空值","d":"表示这里没有值。DiskScheduler 析构时往队列放它，让后台线程退出。","a":["nullopt"],"h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"std::move","f":"把对象转成右值","d":"让资源转移而不是拷贝。页守卫、unique_ptr 这类不可拷贝的对象都靠它传递。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"std::mutex","f":"C++ 互斥锁","d":"同一时刻只让一个线程进入临界区，抢不到就睡眠。Linux 上底层是 futex。","h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"std::shared_mutex","f":"C++ 读写锁","d":"多个读线程可以同时持有，写线程独占。就是第 10 讲的读写 latch。","a":["shared_mutex"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"std::atomic","f":"C++ 原子类型","d":"对它的读改写不会被其他线程打断，不用加锁。BusTub 的 pin 计数用的就是它。","a":["atomic"],"h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"std::atomic_flag","f":"C++ 最简单的原子布尔","d":"只有测试并设置和清除两个操作，就是第 10 讲的自旋 latch。","h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"std::lock_guard","f":"RAII 锁守卫","d":"构造时加锁，离开作用域自动放锁，不能中途放开。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"std::scoped_lock","f":"C++17 的 RAII 锁守卫","d":"和 std::lock_guard 类似，但能一次锁住多个互斥量而不死锁。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"std::unique_lock","f":"可手动控制的独占锁守卫","d":"比 std::lock_guard 灵活，能中途放锁再加锁，可以配合条件变量使用。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"std::shared_lock","f":"共享模式的锁守卫","d":"以读模式持有 std::shared_mutex，离开作用域自动放锁。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"std::promise","f":"一次性结果通道的写入端","d":"一个线程用 set_value 写入结果。DiskScheduler 用它告诉发起方 I/O 完成了。","a":["std::promise/future"],"h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"std::future","f":"一次性结果通道的读取端","d":"从 std::promise 拿到，调用 get() 等待结果就绪。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"std::unique_ptr","f":"独占所有权的智能指针","d":"不能拷贝只能移动，离开作用域自动释放对象。","a":["unique_ptr"],"h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"std::shared_ptr","f":"引用计数的智能指针","d":"最后一个持有者销毁时才释放对象。","a":["shared_ptr"],"h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"std::unordered_map","f":"C++ 标准库的哈希表","d":"好用但不受缓冲池管理，所以数据库的页内结构不用它。","a":["unordered_map"],"h":"../ch03-indexes.html#L07","n":"详见 #07 哈希表"},{"t":"std::terminate","f":"C++ 运行时终止程序的函数","d":"异常没人接住时会走到这里，进程立刻结束。析构函数里抛异常就是这样。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"BusTub","f":"CMU 自研的教学数据库","d":"本课的 Project 都在它上面做，用 C++ 写成，从缓冲池一路做到 MVCC。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"CountMinSketch","f":"P0 要实现的 Count-Min Sketch","d":"用计数矩阵和多个哈希函数估算元素频次，只会高估不会低估。","h":"../lab.html#P0","n":"详见 P0 Project 0：C++ Primer"},{"t":"BufferPoolManager","f":"BusTub 的缓冲池管理器","d":"P1 的核心：管理内存帧，负责按页号取页、pin 计数、脏页写回和淘汰。","a":["BPM"],"h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"ArcReplacer","f":"ARC 替换策略的实现","d":"用两个存活列表和两个 ghost 列表决定淘汰哪一帧，是 P1 的 Task 1。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"FrameHeader","f":"缓冲池里一帧的元数据","d":"记录帧号、读写锁、pin 计数、脏标志，还有这一帧 8 KB 的数据。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"DiskScheduler","f":"磁盘请求调度器","d":"把读写请求放进 Channel，由后台线程交给 DiskManager 执行，完成后用 promise 通知。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"DiskManager","f":"BusTub 的磁盘读写层","d":"实际把页写进数据库文件、再读回来。已经写好，由 DiskScheduler 的后台线程调用。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"DiskRequest","f":"一次磁盘读写请求","d":"包含读写标志、内存地址、页号，以及一个用来通知完成的 std::promise。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"Channel","f":"线程安全的队列模板","d":"多生产者多消费者：Put 放入，Get 取出，队列空时阻塞。DiskScheduler 用它传请求。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"ReadPageGuard","f":"读页守卫","d":"RAII 包装：持有页的共享锁和 pin，Drop 或析构时自动释放。可移动、不可拷贝。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"WritePageGuard","f":"写页守卫","d":"和 ReadPageGuard 一样的 RAII 包装，但持有独占锁，可以修改页内容。","h":"../lab.html#P1","n":"详见 P1 Project 1：缓冲池管理器"},{"t":"TracedBufferPoolManager","f":"带计数的缓冲池包装","d":"在 BPM 外面包一层，统计读写页的次数。P2 的测试用它检查有没有多读页。","h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"BPlusTree","f":"P2 的 B+ 树主类","d":"实现点查、插入、删除和迭代器，并要支持并发（latch crabbing）。","h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"BPlusTreePage","f":"B+ 树页的公共基类","d":"页头放页类型、当前大小和最大大小，内部页和叶子页都继承它。","h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"BPlusTreeHeaderPage","f":"B+ 树的头页","d":"只存根页号。改根之前先拿它的写守卫，避免根被并发替换。","h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"BPlusTreeLeafPage","f":"B+ 树的叶子页","d":"存有序的键和 RID，用下一页指针串成链表。Fall 2025 还加了墓碑。","a":["LeafPage"],"h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"BPlusTreeInternalPage","f":"B+ 树的内部页","d":"存分隔键和子页号，只负责导航。第 0 个键不用。","a":["InternalPage"],"h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"IndexIterator","f":"B+ 树的迭代器","d":"沿叶子页链表顺序遍历键值对，用于范围扫描。","h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"Context","f":"B+ 树操作的上下文（BusTub 类）","d":"存着头页守卫和路径上的读写守卫，latch crabbing 时从这里释放。","h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"Execution Context","f":"执行上下文","d":"表达式求值时带着的环境：当前元组、查询参数、表的 schema，要提前准备好。","h":"../ch04-execution.html#L13","n":"详见 #13 查询执行 I：处理模型、访问方法与表达式求值"},{"t":"GenericKey","f":"BusTub 索引的定长键","d":"N 字节的定长键模板，大小由 GenericComparator 比较。","h":"../lab.html#P2","n":"详见 P2 Project 2：B+ 树索引"},{"t":"AbstractExecutor","f":"所有执行器的基类","d":"定义 Init、Next 和 GetOutputSchema。这里的 Next 每次产出一批元组，不是一条。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"ExecutorContext","f":"执行器的运行环境","d":"每个执行器都拿到它，从中取事务、Catalog、缓冲池和事务管理器。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"ExecutionEngine","f":"执行计划的入口","d":"把计划树建成执行器树，先 Init 根执行器，再反复调用 Next 取结果。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"AbstractPlanNode","f":"所有计划节点的基类","d":"计划树的节点，带输出 schema 和子节点，优化器改写的就是这棵树。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"Catalog","f":"BusTub 的系统目录","d":"管理表和索引的元数据，可以按名字或 oid 查到 TableInfo 和 IndexInfo。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"TableInfo","f":"一张表的元数据","d":"存表名、schema、oid 和指向 TableHeap 的指针。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"TableHeap","f":"BusTub 的表堆","d":"把一张表存成一串页，提供插入、按 RID 取元组和遍历。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"TableIterator","f":"表堆的迭代器","d":"逐条扫描表堆里的元组，顺序扫描执行器用它。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"TupleMeta","f":"元组的元信息","d":"存时间戳 ts_ 和删除标记 is_deleted_，每条元组一份。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"NestedLoopJoin","f":"BusTub 的嵌套循环连接","d":"内表要能重新扫：每换一条外表元组，右子执行器都要重新开始。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"HashJoin","f":"BusTub 的哈希连接","d":"优化器规则会把等值连接的 NestedLoopJoin 改写成它，非等值连接不能改。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"TopN","f":"BusTub 的 Top-N 算子","d":"Sort 加 Limit 可以改写成它：用容量为 N 的优先队列，不必全排。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"SimpleAggregationHashTable","f":"聚合用的内存哈希表","d":"键是 AggregateKey，值是 AggregateValue，聚合执行器用它累积结果。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"AggregateKey","f":"聚合的分组键","d":"一组 GROUP BY 表达式的值。靠 std::hash 特化和 operator== 放进哈希表。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"MergeSortRun","f":"外部归并排序的一个 run","d":"记着一串有序页的页号，元组在页内和页间都有序，用迭代器读取。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"IntermediateResultPage","f":"中间结果页","d":"存外部归并排序和哈希连接的中间数据，支持变长元组，页格式自己设计。","h":"../lab.html#P3","n":"详见 P3 Project 3：查询执行"},{"t":"Transaction","f":"事务（BusTub 的事务类）","d":"记录事务 id、读时间戳和提交时间戳、状态、隔离级别，以及 undo 日志和写集合。","h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"TransactionManager","f":"BusTub 的事务管理器","d":"负责开始、提交和中止事务，保管事务表、版本链头和水位线。","h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"UndoLog","f":"版本链上的一条 undo 日志","d":"记着改了哪些字段、这些字段的旧值、时间戳和上一个版本的链接。","h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"UndoLink","f":"指向上一版本的链接","d":"由事务 id 和该事务里的日志下标组成，把 undo 日志串成版本链。","h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"Watermark","f":"BusTub 的水位线类","d":"跟踪所有运行中事务的读时间戳并取最小值，垃圾回收以它为界。","h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"PageVersionInfo","f":"一页的版本链头表","d":"存这一页每个槽对应的 UndoLink，按页号放在 TransactionManager 里。","h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"TxnMgrDbg","f":"打印版本链的调试函数","d":"P4 要自己实现：把表堆和版本链打印出来，调试时最有用。","h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"RID","f":"Record ID · 记录 ID","d":"由页号和槽号组成，唯一定位一条元组。BusTub 里同名的类就是它。","a":["RecordID"],"h":"../ch02-storage.html#L03","n":"详见 #03 数据库存储 I：文件、页、元组"},{"t":"ACID","f":"Atomicity, Consistency, Isolation, Durability · 原子性、一致性、隔离性、持久性","d":"事务要满足的四条保证：全做或全不做、状态合法、互不干扰、提交后不丢。","h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"原子性","f":"Atomicity · 原子性","d":"事务的操作要么全部生效，要么全部撤销，不存在只做了一半的结果。","a":["Atomicity"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"隔离性","f":"Isolation · 隔离性","d":"每个事务跑起来都像系统里只有它一个，不必操心别人同时在改什么。","h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"持久性","f":"Durability · 持久性","d":"事务一旦提交，机器崩溃或断电后改动也还在。","a":["Durability"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"完整性约束","f":"Integrity Constraint · 完整性约束","d":"应用提前声明、数据库强制执行的规则，比如年龄不能为负，挡住非法状态。","a":["integrity constraint"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"可串行化","f":"Serializability · 可串行化","d":"事务虽有交错，结果却等价于某个串行顺序。这是并发控制要守住的正确性标准。","a":["可串行","可串行化调度","Serializable Schedule"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"冲突等价","f":"Conflict Equivalence · 冲突等价","d":"两个调度操作相同，且每一对冲突操作的先后顺序都一样。","h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"冲突可串行化","f":"Conflict Serializability · 冲突可串行化","d":"调度冲突等价于某个串行调度，依赖图无环即成立。真实系统用的都是这个标准。","a":["冲突可串行","Conflict Serializability"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"视图可串行化","f":"View Serializability · 视图可串行化","d":"比冲突可串行更宽：读到的值和最终值与某串行顺序相同即可。没有系统能实现。","a":["视图可串行","View Serializability"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"依赖图","f":"Dependency Graph · 依赖图（优先图）","d":"事务是节点，冲突操作从先发生的连向后发生的。无环才是冲突可串行。","a":["优先图","Dependency Graph","Precedence Graph"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"盲写","f":"Blind Write · 盲写","d":"不读旧值就直接覆盖。视图可串行能容忍这种写，冲突可串行不能。","a":["blind write"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"脏读","f":"Dirty Read · 脏读","d":"读到别的事务还没提交的值；对方一旦中止，读到的就是从未存在过的数据。","a":["Dirty Read"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"不可重复读","f":"Unrepeatable Read · 不可重复读","d":"同一事务读同一对象两次，中间被别人改了，两次的值不一样。","a":["Unrepeatable Read"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"丢失更新","f":"Lost Update · 丢失更新","d":"两个事务的写互相覆盖、交错落地，最终结果不等于任何串行顺序。","a":["Lost Update"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"撕裂写","f":"Torn Write · 撕裂写","d":"一次写只完成了一部分，比如页只落盘一半，留下半新半旧的内容。","a":["撕裂的写","torn write"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"强一致性","f":"Strong Consistency · 强一致性","d":"在一个节点提交后，立刻去别的节点读，也能看到这次写。","a":["强一致"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"最终一致性","f":"Eventual Consistency · 最终一致性","d":"改动传播有个时间窗口，期间可能读到旧版本，之后各副本才趋于一致。","a":["最终一致","Eventual Consistency"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"NoSQL","f":"NoSQL · 非关系型数据库","d":"没有严格定义的一类系统，早期放弃事务和 SQL，如今基本都绕回来了。","h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"外部一致性","f":"External Consistency · 外部一致性","d":"比可串行化更强：事务生效顺序还要和真实先后一致。极少系统支持，如 Spanner。","a":["external consistency","严格可串行化","严格一致性"],"h":"../ch06-concurrency.html#L17","n":"详见 #17 并发控制理论：ACID 与可串行化"},{"t":"Strict 2PL","f":"Strict Two-Phase Locking · 严格两阶段封锁","d":"比基本 2PL 严、比 Strong Strict 松：X 锁留到事务结束，S 锁可以在收缩期放掉。","a":["strict 2PL"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"Strong Strict 2PL","f":"Strong Strict Two-Phase Locking · 强严格两阶段封锁","d":"所有锁都持有到事务结束才一次放完。没有级联中止，但死锁照样会发生。","a":["Rigorous 2PL","强严格"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"增长期","f":"Growing Phase · 增长期","d":"2PL 的前半段：事务只申请锁，不释放。","a":["Growing"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"收缩期","f":"Shrinking Phase · 收缩期","d":"2PL 的后半段：放掉任何一把锁就进入，此后不能再申请新锁。","a":["Shrinking"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"级联中止","f":"Cascading Abort · 级联中止","d":"读过某事务未提交数据的事务要跟着它一起中止，可能牵连一大片。","a":["Cascading Aborts","Cascading Abort"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"锁管理器","f":"Lock Manager · 锁管理器","d":"集中记录谁持有什么锁、谁在排队的哈希表。有全局视野，所以能检测死锁。","a":["Lock Manager","lock manager"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"S 锁","f":"Shared Lock · 共享锁","d":"读对象时拿的锁。多个事务可以同时持有，但和 X 锁互斥。","a":["共享锁"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"X 锁","f":"Exclusive Lock · 排他锁","d":"写对象时拿的锁。持有期间别的事务既拿不到 S 锁，也拿不到 X 锁。","a":["排他锁"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"意向锁","f":"Intention Lock · 意向锁","d":"在上层留个提示，说明下面某处会加什么锁，别的事务不必遍历下层来确认。","a":["Intention Lock"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"Intention-Shared","f":"IS 锁 · 意向共享锁","d":"IS：声明下面某处会拿共享锁。除 X 以外都兼容。","h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"IX","f":"Intention-Exclusive · 意向排他锁","d":"声明下面某处会拿排他锁。与 IS、IX 兼容，与 S、SIX、X 不兼容。","a":["Intention-Exclusive"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"SIX","f":"Shared + Intention-Exclusive · 共享意向排他锁","d":"这一层整个读、下面某处要改：隐含全部 S 锁，只在要改处取 X。只和 IS 兼容。","a":["Shared + Intention-Exclusive"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"层次封锁","f":"Hierarchical Locking · 层次封锁","d":"按库、表、页、元组分层加锁，在高层拿一把就覆盖下面全部，省去大量细锁。","h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"锁升级","f":"Lock Escalation · 锁升级","d":"细锁太多时换成上层一把粗锁，顶掉下面所有细锁；S 锁升成 X 锁也叫升级。","a":["Lock Escalation"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"死锁检测","f":"Deadlock Detection · 死锁检测","d":"定期在等待图里找环，找到就中止一个事务。查太勤费 CPU，太稀事务白等。","h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"死锁预防","f":"Deadlock Prevention · 死锁预防","d":"锁被占时立刻按事务年龄决定等待或中止，让死锁不发生，不需要等待图。","h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"等待图","f":"Waits-For Graph · 等待图","d":"事务是节点，Ti 在等 Tj 持有的锁就连边 Ti→Tj。有环就是死锁。","a":["Waits-For Graph"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"牺牲品","f":"Victim · 牺牲品","d":"死锁时被挑出来中止的事务，常按年龄、已做工作量、持锁数来选。","h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"保存点","f":"Savepoint · 保存点","d":"事务内部的回滚点，只退到这里，不必整个事务重来。由应用显式创建。","a":["Savepoint"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"Wait-Die","f":"Wait-Die · 老的等年轻的","d":"死锁预防：申请者更老就等，更年轻就自杀。等待只朝一个方向，不会成环。","a":["wait-die"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"Wound-Wait","f":"Wound-Wait · 年轻的等老的","d":"死锁预防：申请者更老就抢锁、杀掉持有者，更年轻就等。等待方向单一，不成环。","a":["wound-wait"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"饿死","f":"Starvation · 饿死","d":"某个事务或线程一直拿不到资源，永远做不完。","a":["starvation"],"h":"../ch06-concurrency.html#L18","n":"详见 #18 两阶段封锁 2PL：锁、死锁与层次封锁"},{"t":"OCC","f":"Optimistic Concurrency Control · 乐观并发控制","d":"不加锁，先把活干完，提交时再验证有没有冲突。冲突少时快，高竞争时全白干。","a":["乐观并发控制","Optimistic Concurrency Control"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"时间戳排序","f":"Timestamp Ordering · 时间戳排序","d":"不用锁，靠时间戳决定事务的串行顺序。OCC 是其中最主流的协议。","a":["Timestamp Ordering"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"私有工作区","f":"Private Workspace · 私有工作区","d":"OCC 给每个事务的专属空间，改动都关在里面，验证通过才装进全局数据库。","a":["Private Workspace","private workspace"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"读阶段","f":"Read Phase · 读阶段","d":"OCC 第一阶段。名字叫读，其实读写都在这里做，全部发生在私有工作区。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"验证阶段","f":"Validation Phase · 验证阶段","d":"OCC 第二阶段。此刻才分配时间戳，检查自己的改动会不会破坏串行顺序。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"写阶段","f":"Write Phase · 写阶段","d":"OCC 第三阶段。验证通过后，把私有工作区的改动原子地装进全局数据库。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"前向验证","f":"Forward Validation · 前向验证","d":"和还在跑的活跃事务比读写集，看我改的东西有没有别人正在读。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"后向验证","f":"Backward Validation · 后向验证","d":"和已提交的事务比，看它们的改动我有没有漏读。实现简单，是主流做法。","a":["Backward Validation"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"读写集","f":"Read Set / Write Set · 读集 / 写集","d":"事务读过、写过的对象集合，OCC 比对它们判冲突。Latch 那边的写集用于自己回滚。","a":["读集","写集","Write Set","write set"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"事务状态表","f":"Transaction Status Table · 事务状态表","d":"内存里记录各事务时间戳和状态的表。判断版本可见性、提交与否都要查它。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"时间戳回绕","f":"Timestamp Wraparound · 时间戳回绕","d":"计数器位数有限，用尽后绕回小值，造成逻辑上的过去和未来错乱。","a":["回绕"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"幻读","f":"Phantom Read · 幻读","d":"同一事务里重复做范围查询，别人插入或删除的行凭空出现或消失。","a":["Phantom Read"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"谓词封锁","f":"Predicate Locking · 谓词封锁","d":"不锁元组，锁 WHERE 条件划出的区域，区域相交即冲突。能防幻读但 NP-hard。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"精确封锁","f":"Precision Locking · 精确封锁","d":"谓词封锁的可行近似：拿 WHERE 条件去查读写集，看有没有重叠。","a":["Precision Locking"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"索引封锁","f":"Index Locking · 索引封锁","d":"用索引当锁的载体来表达范围，连不存在的键也能锁住。防幻读最常见的办法。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"键值锁","f":"Key-Value Lock · 键值锁","d":"锁住索引里一个确定存在的键，是索引封锁最基础的一层。","a":["Key-Value Lock"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"间隙锁","f":"Gap Lock · 间隙锁","d":"锁住两个相邻键之间的空隙，挡住往里插入新值，从而防幻读。","a":["Gap Lock"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"键范围锁","f":"Key-Range Lock · 键范围锁","d":"把一个键和它后面的间隙合成一把锁，防止别人往这个范围里插入。","a":["Key-Range Lock"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"侦察事务","f":"Reconnaissance Transaction · 侦察事务","d":"先把事务跑一遍但不改数据，记下扫描集、查出约束违规，真正提交时再跑。","a":["reconnaissance transaction"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"隔离级别","f":"Isolation Level · 隔离级别","d":"事务之间隔离到什么程度。级别越低，允许的异常越多，并行度越高。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"SERIALIZABLE","f":"SERIALIZABLE · 可串行化级别","d":"最高隔离级别，脏读、不可重复读、幻读都不会出现。多数系统默认不是它。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"REPEATABLE READ","f":"REPEATABLE READ · 可重复读","d":"同一事务重复读同一对象，值不变；但范围查询仍可能有幻读。","a":["可重复读"],"h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"READ COMMITTED","f":"READ COMMITTED · 读已提交","d":"只读得到已提交的数据，但同一事务两次读可能不同。多数系统的默认级别。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"READ UNCOMMITTED","f":"READ UNCOMMITTED · 读未提交","d":"最低隔离级别，不取共享锁，可能读到别人没提交的值，三种异常都可能出现。","h":"../ch06-concurrency.html#L19","n":"详见 #19 时间戳排序与 OCC：乐观并发控制、幻读与隔离级别"},{"t":"快照隔离","f":"Snapshot Isolation · 快照隔离","d":"事务看到它开始那一刻已提交数据的一致快照。写冲突先写者胜，但有写偏斜。","a":["Snapshot Isolation"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"写偏斜","f":"Write Skew · 写偏斜","d":"两个事务读同一快照、各改不同对象，单看没冲突，合起来却不等于任何串行结果。","a":["Write Skew"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"SSI","f":"Serializable Snapshot Isolation · 可串行化快照隔离","d":"在快照隔离上多维护一张依赖图，杀掉会造成写偏斜的事务，做到可串行化。","a":["可串行化快照隔离"],"h":"../ch09-review.html#L25","n":"详见 #25 期末复习 + 现代 OLAP 引擎速成"},{"t":"First Writer Wins","f":"First Writer Wins · 先写者胜","d":"快照隔离的写冲突规则：第一个写的事务赢，后来者中止。","a":["先写者胜"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"逻辑元组","f":"Logical Tuple · 逻辑元组","d":"应用眼里的一条记录，由主键标识。MVCC 下它对应多个物理版本。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"物理版本","f":"Physical Version · 物理版本","d":"逻辑元组的一份实际副本。每次更新都新建一个，事务任一时刻只看到其中一个。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"版本链","f":"Version Chain · 版本链","d":"把同一逻辑元组的各版本用指针串成链表，索引指向链头，沿链找可见版本。","a":["Version Chain","version chain"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"N2O","f":"Newest-to-Oldest · 新到旧","d":"版本链从最新版本开始。读最新版最快，但每次更新都要改索引指针。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"O2N","f":"Oldest-to-Newest · 旧到新","d":"版本链从最旧版本开始。找最新版要走到底，但更新时索引不用改。PostgreSQL 用它。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"版本存储","f":"Version Storage · 版本存储","d":"MVCC 把旧版本放在哪，有追加式、时间旅行式、增量式三种方案。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"GC","f":"Garbage Collection · 垃圾回收","d":"清理不再需要的内容。MVCC 里指回收无人可见的旧版本和中止事务留下的版本。","a":["垃圾回收"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"begin-ts","f":"Begin Timestamp · 版本起始时间戳","d":"版本可见区间的左端，也就是创建这个版本的事务的时间戳。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"end-ts","f":"End Timestamp · 版本结束时间戳","d":"版本可见区间的右端，∞ 表示最新版本。判断版本能否回收也靠它。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"可见性判断","f":"Visibility Check · 可见性判断","d":"看时间戳区间和创建者的提交状态，决定某个版本对当前事务是否可见。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"时间旅行查询","f":"Time-Travel Query · 时间旅行查询","d":"不回收旧版本，就能查数据库在过去某一时刻的状态，常用于审计。","a":["Time-Travel Query"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"追加式","f":"Append-Only Storage · 追加式存储","d":"每次更新把整条元组复制一份，追加到同一个表空间。PostgreSQL 的做法。","a":["Append-Only"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"时间旅行式","f":"Time-Travel Storage · 时间旅行式存储","d":"更新时完整复制，存进一张独立的旧版本表，回收时不打扰主表。","a":["Time-Travel"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"增量式","f":"Delta Storage · 增量式存储","d":"主表直接覆盖成最新版，只把被改列的旧值存到别处，读旧版本时倒着打补丁。","a":["Delta Storage"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"delta record","f":"Delta Record · 增量记录","d":"增量式存储里的一条旧值记录，只含被改列的旧值，省去整条拷贝。","a":["增量记录","delta 记录"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"回滚段","f":"Rollback Segment · 回滚段","d":"MySQL、Oracle 存增量记录的地方，水位线一过就能整块丢弃。","a":["Rollback Segment","rollback segment"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"VACUUM","f":"VACUUM · 垃圾回收进程","d":"回收无人能看到的旧版本的后台任务。PostgreSQL 的 VACUUM 不把空间还给操作系统。","a":["vacuum"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"水位线","f":"Watermark · 水位线","d":"活跃事务里最小的时间戳。早于它的旧版本没人能看到，可以回收。","a":["watermark"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"协作式清理","f":"Cooperative Cleaning · 协作式清理","d":"事务沿版本链查找时，顺手清掉谁都看不到的旧版本，让 SELECT 也会写数据。","a":["协作式回收","Cooperative Cleaning"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"落灰的角落","f":"Dusty Corners · 落灰的角落","d":"从没人读的旧版本，协作式清理碰不到，所以还得定期跑全面的 VACUUM。","a":["Dusty Corners"],"h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"物理指针","f":"Physical Pointer · 物理指针","d":"直接记录数据物理位置的指针，如 RecordID。位置一变，所有指向它的索引都得改。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"逻辑指针","f":"Logical Pointer · 逻辑指针","d":"二级索引存主键值而不是物理位置。多一跳间接，但版本链头变化时索引不用改。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"xmin","f":"xmin · PostgreSQL 的 begin-ts","d":"PostgreSQL 暴露的版本元数据：创建这个版本的事务 ID。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"xmax","f":"xmax · PostgreSQL 的 end-ts","d":"PostgreSQL 暴露的版本元数据：相当于 end-ts，0 表示这是最新版本。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"ctid","f":"ctid · PostgreSQL 的 RecordID","d":"PostgreSQL 里版本的物理位置（页号, 槽号），扫描时推导，建新版本后会变。","h":"../ch06-concurrency.html#L20","n":"详见 #20 MVCC 多版本并发控制"},{"t":"read_ts","f":"Read Timestamp · 读时间戳","d":"P4 里事务开始时拿到的时间戳，决定它能看见哪些版本。","a":["读时间戳"],"h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"commit_ts","f":"Commit Timestamp · 提交时间戳","d":"P4 里事务提交时拿到的时间戳，决定它写的东西对谁可见。","a":["提交时间戳"],"h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"undo 日志","f":"Undo Log · undo 日志","d":"记录怎样撤回改动。BusTub 用它串成版本链，读旧版本就是逐条打补丁退回去。","a":["Undo 日志"],"h":"../lab.html#P4","n":"详见 P4 Project 4：并发控制（MVCC）"},{"t":"STEAL","f":"STEAL · 偷取","d":"缓冲池可以把未提交事务改脏的页写回磁盘。运行快，但恢复时必须能 undo。","a":["Steal"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"NO-STEAL","f":"NO-STEAL · 不偷取","d":"未提交事务改脏的页不许写盘，磁盘上只有已提交数据，所以不需要 undo。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"FORCE","f":"FORCE · 强制刷盘","d":"事务提交前必须把它改的脏页全部刷盘。不需要 redo，但运行时慢。","a":["Force"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"NO-FORCE","f":"NO-FORCE · 不强制刷盘","d":"提交时不必刷脏页，只要日志落盘。运行快，但恢复时必须能 redo。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"Undo","f":"Undo · 撤销","d":"抹掉未完成或已中止事务的影响。STEAL 策略下必须支持。","a":["undo","UNDO"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"Redo","f":"Redo · 重做","d":"重新应用已提交事务的改动，确保它们真的在。NO-FORCE 策略下必须支持。","a":["redo","REDO"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"影子分页","f":"Shadow Paging · 影子分页","d":"改动写在页的副本上，提交时原子翻转主指针。恢复瞬间完成，但运行慢、有碎片。","a":["Shadow Paging"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"主指针","f":"Master Pointer · 主指针","d":"影子分页里指向当前页目录的记录。对它的一次原子写，让整个事务一键生效。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"回滚日志","f":"Rollback Journal · 回滚日志","d":"SQLite 的影子分页变体：改页前先把旧页存进日志文件，崩溃后写回去恢复。","a":["rollback mode"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"组提交","f":"Group Commit · 组提交","d":"把一小段时间内多个事务的日志打包，一次 fsync 写盘，大幅提高提交吞吐。","a":["Group Commit"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"同步提交","f":"Synchronous Commit · 同步提交","d":"等日志真正落盘才回复提交成功。不开的话，崩溃时可能丢已提交的数据。","a":["synchronous commit"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"提交点","f":"Commit Point · 提交点","d":"事务真正算提交的那一刻：COMMIT 记录连同之前的日志落盘时。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"物理日志","f":"Physical Logging · 物理日志","d":"记字节级 diff：某页某偏移的旧值和新值。恢复快，但改多少条就记多少条。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"逻辑日志","f":"Logical Logging · 逻辑日志","d":"只记 SQL 语句本身，日志量极小，但恢复要重新执行，还怕非确定性函数。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"物理逻辑日志","f":"Physiological Logging · 物理逻辑日志","d":"记哪个页的哪个槽改成了什么，页内可以自由重组。多数系统用它。","a":["Physiological Logging","Physiological"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"CDC","f":"Change Data Capture · 变更数据捕获","d":"读取数据库的 WAL，把变更流式发给其他系统，如数据仓库。","a":["变更数据捕获","Change Data Capture"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"检查点","f":"Checkpoint · 检查点","d":"把脏页刷盘并在日志里留记号，恢复时只需回看到这里，日志也不用无限增长。","a":["Checkpoint","checkpoint","CHECKPOINT"],"h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"阻塞式检查点","f":"Blocking Checkpoint · 阻塞式检查点","d":"暂停所有事务、刷完全部脏页再继续。简单，但缓冲池大时停顿不可接受。","h":"../ch07-recovery.html#L21","n":"详见 #21 预写日志 WAL 与影子分页"},{"t":"ARIES","f":"Algorithms for Recovery and Isolation Exploiting Semantics","d":"崩溃恢复的黄金标准：WAL、重放历史、给撤销记日志，分析重做撤销三阶段。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"模糊检查点","f":"Fuzzy Checkpoint · 模糊检查点","d":"不暂停事务打检查点，记下开始那一刻的 ATT 和 DPT，靠它们去日志里还原真相。","a":["Fuzzy Checkpoint","fuzzy checkpoint"],"h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"CHECKPOINT-BEGIN","f":"模糊检查点的开始记录","d":"模糊检查点的起点日志。MasterRecord 指向它，分析阶段从这里开始。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"CHECKPOINT-END","f":"模糊检查点的结束记录","d":"模糊检查点的结束日志，里面放着 BEGIN 那一刻的 ATT 和 DPT 快照。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"DPT","f":"Dirty Page Table · 脏页表","d":"记录当前有哪些脏页、各自最早让它变脏的日志，恢复时据此决定重做起点。","a":["脏页表","Dirty Page Table"],"h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"ATT","f":"Active Transaction Table · 活跃事务表","d":"记录活跃事务的状态和 lastLSN，恢复时据此找出要回滚的事务。","a":["活跃事务表","Active Transaction Table"],"h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"CLR","f":"Compensation Log Record · 补偿日志记录","d":"撤销一个改动时写的日志，让撤销本身也可恢复、可续做。CLR 不会再被撤销。","a":["补偿日志记录","Compensation Log Record"],"h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"recLSN","f":"Recovery LSN · 页变脏的起始 LSN","d":"自这页上次刷盘以来，第一条修改它的日志的 LSN，存在 DPT 里。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"flushedLSN","f":"Flushed LSN · 已落盘的最大 LSN","d":"已经刷到磁盘的最大 LSN。页的 pageLSN 不超过它，这页才能刷盘。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"prevLSN","f":"Previous LSN · 同事务的上一条 LSN","d":"把同一事务的日志记录串成反向链表，回滚时不用在交织的日志里找。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"lastLSN","f":"Last LSN · 事务最近一条 LSN","d":"某事务最近一条日志的 LSN，存在 ATT 里，中止时从这里开始往回走。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"undoNext","f":"undoNextLSN · 下一条待撤销记录","d":"CLR 里的字段，指向下一条还要撤销的日志。恢复中再崩，也能从这里接着撤。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"MasterRecord","f":"Master Record · 主记录","d":"存在磁盘上，记录最后一次成功检查点的起点，恢复从这里开始找。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"TXN-END","f":"Transaction End · 事务结束记录","d":"表示事务彻底完结，可从 ATT 里删掉。提交和中止都要写，不需要立即刷盘。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"重放历史","f":"Repeating History · 重放历史","d":"恢复时把日志里的改动全部重做一遍，包括 CLR，宁可多做不能漏做。","a":["Repeating History"],"h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"分析阶段","f":"Analysis Phase · 分析阶段","d":"ARIES 第一步：从最近的检查点扫到日志末尾，重建 ATT 和 DPT。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"重做阶段","f":"Redo Phase · 重做阶段","d":"ARIES 第二步：从 DPT 最小的 recLSN 开始重放，靠 pageLSN 跳过已应用的改动。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"撤销阶段","f":"Undo Phase · 撤销阶段","d":"ARIES 第三步：反向回滚崩溃时没提交的事务，每撤一步写一条 CLR。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"幂等","f":"Idempotent · 幂等","d":"同一操作重复做多次，结果和做一次一样。所以重做阶段崩了重跑即可。","h":"../ch07-recovery.html#L22","n":"详见 #22 崩溃恢复：ARIES"},{"t":"逻辑正确性","f":"Logical Correctness · 逻辑正确性","d":"我该看到的数据看到了吗。由 Lock 保护，是事务并发控制要解决的问题。","a":["Logical Correctness"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"物理正确性","f":"Physical Correctness · 物理正确性","d":"数据结构内部是否自洽、指针有没有指错。由 Latch 保护，和事务无关。","a":["Physical Correctness"],"h":"../ch03-indexes.html#L10","n":"详见 #10 索引并发控制：Latch 与 Latch Crabbing"},{"t":"Shared-Nothing","f":"Shared-Nothing · 无共享架构","d":"每个节点有自己的内存和磁盘，只靠网络通信。性能好，但扩容要搬数据。","a":["shared-nothing","Shared-nothing"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"Shared-Disk","f":"Shared-Disk · 共享磁盘架构","d":"节点有各自的 CPU 和内存，数据都在共享存储上。扩容只改目录，云时代主流。","a":["shared-disk","Shared-disk"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"Shared-Everything","f":"Shared-Everything · 共享一切架构","d":"CPU、内存、磁盘都在本地，也就是单机数据库。","a":["shared-everything"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"水平分区","f":"Horizontal Partitioning · 水平分区（分片）","d":"按分区键把一张表的行切到不同节点，最常见的分区方式。","a":["分片","Sharding","sharding","Horizontal Partitioning"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"分区键","f":"Partition Key · 分区键","d":"决定一行归属哪个分区的列。查询不带它，就只能广播给所有节点。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"哈希分区","f":"Hash Partitioning · 哈希分区","d":"按 hash(key) 分配数据。分布式下范围查询要广播，增删节点几乎全要搬。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"范围分区","f":"Range Partitioning · 范围分区","d":"按连续的值区间切分数据。增删节点时要重新洗牌。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"一致性哈希","f":"Consistent Hashing · 一致性哈希","d":"键和节点都映射到环上，键归顺时针遇到的第一个节点。增删节点只搬一段弧。","a":["Consistent Hashing"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"Rendezvous 哈希","f":"Rendezvous Hashing · 汇合哈希（最高随机权重）","d":"键和每个节点 ID 拼起来分别哈希，分数最高的节点拥有它。增删节点只搬少量键。","a":["Rendezvous Hashing","Rendezvous","汇合哈希","最高随机权重"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"主-副本","f":"Primary-Replica · 主-副本","d":"每个对象有一个主节点，写都先到它，再由它扩散给副本。最常见的复制配置。","a":["Primary-Replica"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"多主","f":"Multi-Primary · 多主","d":"任意节点都能写，之后再解决冲突，比主-副本少见。","a":["Multi-Primary"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"K-Safety","f":"K-Safety · K 安全性","d":"系统保持可用所需的最少存活副本数。低于 K 就停止更新，宁可停机也不丢数据。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"领导者选举","f":"Leader Election · 领导者选举","d":"主节点挂了或没有主时，节点们选出新的主。本身就像一次事务。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"计划片段","f":"Plan Fragment · 计划片段","d":"查询计划切下的一段，发到数据所在节点执行，只把结果传回来。","a":["plan fragment"],"h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"TP Monitor","f":"Transaction Processing Monitor · 事务处理监视器","d":"老式集中式协调者：维护全局锁表和事务视图，协调跨节点事务的提交。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"中间件","f":"Middleware · 中间件","d":"架在各分区前面的一层，所有查询走它路由并管锁表，对应用就像一个数据库实例。","h":"../ch08-distributed.html#L23","n":"详见 #23 分布式数据库 I：架构、分区与复制"},{"t":"原子提交协议","f":"Atomic Commit Protocol · 原子提交协议","d":"让所有节点对事务提交还是中止达成同一决定，2PC、Paxos、Raft 都是。","a":["原子提交","Atomic Commit Protocol"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"共识协议","f":"Consensus Protocol · 共识协议","d":"让多个节点就同一决定达成一致。在事务场景里它就是原子提交协议。","a":["Consensus Protocol"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"2PC","f":"Two-Phase Commit · 两阶段提交","d":"协调者先问参与者能否提交，全票通过才下令提交。一个节点挂了就会阻塞。","a":["两阶段提交","Two-Phase Commit"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"3PC","f":"Three-Phase Commit · 三阶段提交","d":"为解决 2PC 的阻塞问题提出的协议，太复杂，没人用。","a":["三阶段提交"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"协调者","f":"Coordinator · 协调者","d":"负责统筹的节点。在 2PC 里主持提交：问所有参与者能否提交，再宣布结果。","a":["Coordinator"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"参与者","f":"Participant · 参与者","d":"事务读写过数据的节点，投票决定能否提交。2PC 只在这些节点上跑。","a":["Participant"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"提前投票","f":"Early Prepare Voting · 提前投票","d":"发最后一条查询时捎带提交投票。要求应用确知这是最后一条，所以罕见。","a":["Early Prepare Voting"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"提前确认","f":"Early Acknowledgement · 提前确认","d":"第一阶段全票后就告诉应用已提交，再去跑第二阶段。","a":["Early Acknowledgement"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"Paxos","f":"","d":"只要多数派同意就能提交的共识协议，部分节点掉线也不阻塞。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"Multi-Paxos","f":"","d":"先选出 leader，之后只由它提议提交，避免多个提议者互相打断。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"Raft","f":"","d":"以好理解为设计目标的共识协议，高层类似 Multi-Paxos，选主看谁的日志最新。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"提议者","f":"Proposer · 提议者","d":"Paxos 里发起提议的角色，对应 2PC 的协调者。","a":["Proposer"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"接受者","f":"Acceptor · 接受者","d":"Paxos 里对提议投票的角色，对应 2PC 的参与者。","a":["Acceptor"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"学习者","f":"Learner · 学习者","d":"Paxos 里只观察状态机变化、没有投票权的节点。","a":["Learner"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"活性","f":"Liveness · 活性","d":"假设总有足够的节点活着，让系统能往前推进；不保证事务一定能提交。","a":["liveness"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"BFT","f":"Byzantine Fault Tolerance · 拜占庭容错","d":"节点可能恶意作假时仍能达成一致的协议。区块链要用它，代价是慢得多。","a":["拜占庭容错","拜占庭"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"租约","f":"Lease · 租约","d":"leader 身份的有效期，要定期续。续太勤浪费，太稀则 leader 挂了发现得慢。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"CAP","f":"Consistency, Availability, Partition Tolerance · CAP 定理","d":"一致性、可用性、分区容忍最多得二。实际问题是网络分区时保哪个。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"PACELC","f":"Partition: Availability / Consistency; Else: Latency / Consistency","d":"在 CAP 上加入延迟：没有网络分区时，也要在延迟和一致性之间取舍。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"网络分区","f":"Network Partition · 网络分区","d":"网络断开，节点分成互不相通的几部分，彼此都以为对方挂了。","h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"脑裂","f":"Split Brain · 脑裂","d":"网络分区后两边都认为自己是主库，各自提交，恢复后数据冲突。","a":["Split Brain","split brain"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"最后写入者胜","f":"Last Writer Wins · 最后写入者胜","d":"合并冲突时比时间戳，最新的赢。多数 NoSQL 用这个。","a":["Last Writer Wins","last writer wins"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"向量时钟","f":"Vector Clocks · 向量时钟","d":"合并冲突的一种办法：读时返回整条版本链，由客户端决定用哪个。Andy 不推荐。","a":["Vector Clocks"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"广播连接","f":"Broadcast Join · 广播连接","d":"把足够小的表复制到每个参与节点，退化成本地连接再合并。","a":["Broadcast Join","broadcast join","broadcast hash join"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"Shuffle 连接","f":"Shuffle Join · Shuffle 连接","d":"两张表都按连接键在线重新分区，让相同的键落到同一节点，再本地连接。","a":["Shuffle Join","shuffle join","shuffle hash join"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"Shuffle","f":"Shuffle · 数据重分布","d":"查询中途按键把数据重新分布到各节点。分布式 OLAP 最大的瓶颈，也能解决倾斜。","a":["shuffle"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"半连接","f":"Semi-Join · 半连接","d":"不搬整张表，只传连接必需的那点信息，比如过滤后的列或 Bloom Filter。","a":["Semi-Join"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"事实表","f":"Fact Table · 事实表","d":"巨大的主表，一行一笔业务记录，比如每一笔订单。","a":["Fact Table"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"},{"t":"维度表","f":"Dimension Table · 维度表","d":"小的、通常只读的旁表，放商品名、邮编这类描述信息。","a":["Dimension Table"],"h":"../ch08-distributed.html#L24","n":"详见 #24 分布式数据库 II：原子提交、CAP 与分布式连接"}];
/* gloss.js —— 术语提示卡：鼠标移到缩写 / 专有名词上，弹一张小卡片显示全称和简短解释。主笔记和 Lab 笔记共用。
 * 词表在 _src/glossary/*.json，构建时写进 window.GLOSS = [{ t 名称, f 全称, d 解释, a 别名, h 链接, n 链接文字 }]。
 * 标记在页面脚本里加（不改 Markdown 也不进构建产物）：每次出现都带一条淡淡的细下划线，鼠标移上去有卡片。
 *   Gloss.scan(el)   给 el 里的术语加标记（可重复调用，已标记的跳过）
 *   Gloss.clear(el)  去掉 el 里的标记（进入编辑模式时用，保存的修改里不会混进标记）
 *   Gloss.watch(el)  el 里的内容以后变了也自动加标记（Lab 笔记的组件会反复重绘）
 */
(function (root) {
'use strict';
var G = root.GLOSS || [], map = Object.create(null), re = null;
/* 这些地方不加标记：链接、代码块、按钮、动画和图、小标签 */
var SKIP = 'a,pre,kbd,code,svg,button,input,select,option,textarea,script,style,summary,.gl,.viz,.dg,.chip,.kick,.hn,.lvl,.lvs,.lvsum,.vz-src,.vz-svg,.vz-out,.code,.cl,.cmd,.out,.badge,.sid,.w-hd,.c-pl';
var ALNUM = /[A-Za-z0-9_]/;

function esc(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function html(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
function init() {
  var words = [];
  G.forEach(function (e, i) { [e.t].concat(e.a || []).forEach(function (w) { map[w] = i; words.push(w); }); });
  words.sort(function (a, b) { return b.length - a.length; });     /* 长的优先：Strict 2PL 先于 2PL */
  re = words.length ? new RegExp(words.map(esc).join('|'), 'g') : null;
}
/* 英文词两边不能再连着字母数字（LSN 不匹配 GRSN），中文词不用看 */
function bounded(s, a, b) {
  return !(ALNUM.test(s.charAt(a)) && a > 0 && ALNUM.test(s.charAt(a - 1))) && !(ALNUM.test(s.charAt(b - 1)) && b < s.length && ALNUM.test(s.charAt(b)));
}
function mark(id) {
  var sp = document.createElement('span');
  sp.className = 'gl'; sp.setAttribute('data-g', id);
  return sp;
}
function scan(scope) {
  if (!re || !scope) return;
  var w = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, { acceptNode: function (n) { return n.parentElement && n.parentElement.closest(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; } });
  var nodes = [], n;
  while ((n = w.nextNode())) { if (n.nodeValue.trim()) nodes.push(n); }
  nodes.forEach(function (t) {
    var s = t.nodeValue, m, last = 0, frag = null;
    re.lastIndex = 0;
    while ((m = re.exec(s))) {
      var a = m.index, b = a + m[0].length;
      if (!bounded(s, a, b)) { re.lastIndex = a + 1; continue; }
      frag = frag || document.createDocumentFragment();
      frag.appendChild(document.createTextNode(s.slice(last, a)));
      var sp = mark(map[m[0]]); sp.textContent = m[0];
      frag.appendChild(sp); last = b;
    }
    if (frag) { frag.appendChild(document.createTextNode(s.slice(last))); t.parentNode.replaceChild(frag, t); }
  });
  /* 行内代码：整段内容正好是一个术语才标（pageLSN 这种），整个 <code> 包起来 */
  Array.prototype.forEach.call(scope.querySelectorAll('code'), function (c) {
    var p = c.parentElement;
    if (!p || p.closest(SKIP) || !(c.textContent in map)) return;
    var sp = mark(map[c.textContent]);
    p.replaceChild(sp, c); sp.appendChild(c);
  });
}
function clear(scope) {
  if (!scope) return;
  Array.prototype.forEach.call(scope.querySelectorAll('.gl'), function (e) {
    var p = e.parentNode;
    while (e.firstChild) p.insertBefore(e.firstChild, e);
    p.removeChild(e); p.normalize();
  });
}
function watch(el) {
  var pending = [], raf = 0, ob;
  function flush() {
    raf = 0;
    var list = pending; pending = [];
    ob.disconnect();
    list.forEach(function (x) { if (x.isConnected) scan(x); });
    ob.observe(el, { childList: true, subtree: true });
  }
  ob = new MutationObserver(function (ms) {
    ms.forEach(function (m) {
      var t = m.target;
      if (t.closest && t.closest('svg,.vz-src,.gl')) return;
      if (t.nodeType === 1 && pending.indexOf(t) < 0) pending.push(t);
    });
    if (pending.length && !raf) raf = requestAnimationFrame(flush);
  });
  scan(el);
  ob.observe(el, { childList: true, subtree: true });
}

/* ════════ 小卡片 ════════ */
var card = null, tShow = 0, tHide = 0, cur = null;
function ensure() {
  if (card) return card;
  var st = document.createElement('style');
  /* 淡淡的细下划线：不支持 color-mix 的浏览器退回到灰色 */
  st.textContent = '.gl{cursor:help;text-decoration:underline solid 1px var(--muted);text-decoration-color:color-mix(in srgb,var(--accent-ink) 32%,transparent);text-underline-offset:3px}' +
    '.gl:hover,.gl.on{color:var(--accent-ink);background:var(--accent-soft);border-radius:3px}' +
    'h1 .gl,h2 .gl,h3 .gl,h4 .gl{text-decoration:none}' +
    '.glcard{position:fixed;z-index:60;max-width:min(340px,calc(100vw - 20px));background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,.18);padding:10px 13px 11px;font:14px/1.6 var(--sans);display:none}' +
    '.glcard.on{display:block}.glcard .t{display:block;font-size:15px;font-weight:700}.glcard .f{color:var(--accent-ink);font-size:13px;line-height:1.5;margin:1px 0 5px}' +
    '.glcard p{margin:0}.glcard .s{display:inline-block;margin-top:6px;font-size:12.5px;color:var(--accent-ink)}@media print{.gl{text-decoration:none}.glcard{display:none!important}}';
  document.head.appendChild(st);
  card = document.createElement('div');
  card.className = 'glcard'; card.setAttribute('role', 'tooltip');
  card.addEventListener('mouseenter', function () { clearTimeout(tHide); });
  card.addEventListener('mouseleave', function () { hideSoon(); });
  document.body.appendChild(card);
  return card;
}
function show(sp) {
  var e = G[+sp.getAttribute('data-g')]; if (!e) return;
  var c = ensure();
  c.innerHTML = '<span class="t">' + html(e.t) + '</span>' + (e.f ? '<div class="f">' + html(e.f) + '</div>' : '') + '<p>' + html(e.d) + '</p>' + (e.h ? '<a class="s" href="' + html(e.h) + '">' + html(e.n || '详见笔记') + ' ›</a>' : '');
  c.classList.add('on');
  if (cur) cur.classList.remove('on');
  cur = sp; sp.classList.add('on');
  /* 优先放在词的下方，放不下翻到上方；左右不出屏幕。折行的词按鼠标所在的那一段算 */
  var rs = sp.getClientRects(), r = rs[0] || sp.getBoundingClientRect(), W = window.innerWidth, H = window.innerHeight, cw = c.offsetWidth, ch = c.offsetHeight;
  if (show.y != null) Array.prototype.forEach.call(rs, function (x) { if (show.y >= x.top && show.y <= x.bottom) r = x; });
  var top = r.bottom + 6 + ch > H - 8 ? r.top - ch - 6 : r.bottom + 6;
  c.style.left = Math.max(8, Math.min(r.left, W - cw - 10)) + 'px';
  c.style.top = Math.max(8, top) + 'px';
}
function hide() { if (card) card.classList.remove('on'); if (cur) cur.classList.remove('on'); cur = null; }
function hideSoon() { clearTimeout(tHide); tHide = setTimeout(hide, 160); }
function active() { return !document.body.classList.contains('editing'); }
document.addEventListener('mouseover', function (ev) {
  var sp = ev.target.closest && ev.target.closest('.gl');
  if (!sp || !active()) return;
  clearTimeout(tHide); clearTimeout(tShow);
  show.y = ev.clientY;
  tShow = setTimeout(function () { show(sp); }, 120);
});
document.addEventListener('mouseout', function (ev) {
  var sp = ev.target.closest && ev.target.closest('.gl');
  if (sp) { clearTimeout(tShow); hideSoon(); }
});
/* 触屏没有悬停：点一下显示，点别处收起 */
document.addEventListener('click', function (ev) {
  var t = ev.target.closest ? ev.target : null; if (!t) return;
  var sp = t.closest('.gl');
  if (sp && active()) { show.y = ev.clientY; show(sp); return; }
  if (!t.closest('.glcard')) hide();
});
document.addEventListener('keydown', function (ev) { if (ev.key === 'Escape') hide(); });
window.addEventListener('scroll', hide, true);

init();
ensure();      /* 样式一加载就要有：下划线不能等到第一次悬停才出现 */
root.Gloss = { scan: function (el) { scan(el); }, clear: clear, watch: watch };
})(window);
